{
  "parameters": [
    {
      "definition": "Size of the grid (number of rows and columns)",
      "symbol": "n",
      "shape": []
    },
    {
      "definition": "Fill-a-Pix puzzle grid where X represents an unknown cell and a number represents a clue",
      "symbol": "puzzle",
      "shape": [
        "n",
        "n"
      ]
    }
  ],
  "output": [
    {
      "definition": "Fill-a-Pix puzzle grid where 1 represents a filled cell and a 0 represents an empty cell",
      "symbol": "grid",
      "shape": [
        "n",
        "n"
      ]
    }
  ],
  "description": "The Fill-a-Pix problem is a Minesweeper-like puzzle based on a grid with a pixilated picture hidden inside. The puzzle consists of a grid containing clues in various places. The objective is to reveal a hidden picture by painting the squares directly around each clue so that the number of painted squares, including the square with the clue, matches the value of the clue. Given a grid with the clues, find which squares should be painted.",
  "metadata": {
    "name": "Fill-a-Pix",
    "domain": "Puzzles and Games",
    "objective": "satisfaction",
    "source": "hakank",
    "constraints": [
      "sum",
      "implies",
      "<=",
      ">",
      "and",
      "forall"
    ],
    "identifier": "puzzles_problem_31"
  }
}

model.mzn:
% number of rows
int: n;
% clues in the grid
array[1..n, 1..n] of -1..9: puzzle;
% solution grid
array[1..n, 1..n] of var 0..1: grid;
% -1 represents a blank
int: X = -1; 

% satisfaction
solve satisfy;

% the number of neighboring painted squares must be equal to the value of the clue for every clue
constraint
    forall(i,j in 1..n) (
      (
       (puzzle[i,j] >= 0)
        ->
        puzzle[i,j] = sum(a,b in {-1,0,1} where 
            i+a > 0  /\ j+b >  0 /\
            i+a <= n /\ j+b <= n
         )
           (grid[i+a,j+b])
      )
    )
;

% output
output [
   if j = 1 then ",\n" else "," endif ++
     show(grid[i,j])
   | i, j in 1..n
]
++
["\n"]
;

