  [
    10, 20, 30, 40,  % Aircraft 1 costs for Routes 1..4
    20, 30, 40, 50,  % Aircraft 2
    30, 40, 50, 60,  % Aircraft 3
    40, 50, 60, 70   % Aircraft 4
  ]
);

