      "definition": "Array representing the position of each queen on the chessboard",
      "symbol": "queens",
      "shape": [
        "n"
      ]
    }
  ],
  "output": [
    {
      "definition": "Array showing the position of each queen to satisfy the N-Queens puzzle",
      "symbol": "queens",
      "shape": [
        "n"
      ]
    }
  ],
  "description": "The N-Queens problem is to place N queens on an N x N chessboard so that no two queens can attack each other. A queen attacks squares on the same row, column, or diagonal. The challenge is to find a set of positions for the queens where they do not attack each other.",
  "metadata": {
    "name": "N-Queens",
    "domain": "Puzzles and Games",
    "objective": "satisfaction",
    "source": "csplib",
    "constraints": [
      "all_different"
    ],
    "identifier": "CSPLib_54"
  }
}

model.mzn:
% 
% n queens problem in MiniZinc.
% 
% This MiniZinc model was created by Hakan Kjellerstrand, hakank@gmail.com
% See also my MiniZinc page: http://www.hakank.org/minizinc
%

% Licenced under CC-BY-4.0 : http://creativecommons.org/licenses/by/4.0/

include "globals.mzn";

int: n;
array[1..n] of var 1..n: queens;

solve :: int_search(
        queens, 
        first_fail, 
        indomain_min, 
        complete) 
    satisfy;

% solve satisfy;

constraint all_different(queens);

constraint
    forall(i, j in 1..n where i < j) (
         queens[i] != queens[j] /\
         queens[i] + i != queens[j] + j /\
         queens[i] - i != queens[j] - j
    ) 
 ;

output [
  show(queens) ++ "\n"

];

