      "definition": "columns chosen in the grid to yield greatest combination",
      "symbol": "cols_chosen",
      "shape": [
        "n"
      ]
    },
    {
      "definition": "Maximum value as a result of choosing the greatest combination",
      "symbol": "max_val",
      "shape": []
    }
  ],
  "description": "The problem is about finding the greatest combination of numbers in a square grid of numbers. The goal is to start at the top of the grid and move down row by row, selecting one number from each row. The selected number from each row forms a combination. The movement from one row to the next can be either straight down, down to the right, or down to the left. The problem is to find the combination that gives the maximum sum. For example, given the grid [[0,2,1,0], [0,1,1,0], [0,10,20,30]], the best move would be indices [1,2,3] for 33 points. Another example is the grid [0,1,1] [0,2,1] [10,0,0], one of the best paths is [1,1,0] for 13 points. The problem is to find the combination that gives the maximum sum and the path that leads to this sum.",
  "metadata": {
    "name": "Seam Carving",
    "domain": "Puzzles and Games",
    "objective": "maximization",
    "source": "hakank",
    "constraints": [
      "forall",
      "abs"
    ],
    "identifier": "puzzles_problem_1"
  }
}

model.mzn:
include "globals.mzn"; 
% input data
int: n; % number of rows
int: m; % number of columns 
array[1..n, 1..m] of int: grid; % grid of values

% decision variables
array[1..n] of var 1..m: cols_chosen; % represents columns chosen from top to bottom
var 0..sum(grid): max_val = sum(i in 1..n) (grid[i, cols_chosen[i]]); % value to be maximized

% solve satisfy;
solve maximize max_val;

%  the movement from one row to the next can be either straight down, down to the right, or down to the left.
constraint
   forall(i in 2..n) (
     let {
       var 1..m: j
     } in
     abs(cols_chosen[i-1]-j) <=1
     /\
     cols_chosen[i] = j
   )
;

% output
output [
  "{\n",
  "  \"max_val\": " ++ show(max_val) ++ ",\n",
  "  \"cols_chosen\": " ++ show(cols_chosen) ++ ",\n",
  "  \"values\": " ++ show([grid[i,fix(cols_chosen[i])] | i in 1..n]) ++ "\n",
  "}"
];

