int: n;
int: num_perms = factorial(n);
array[1..num_perms,1..n] of int: permutations;
int: upper_bound = sum([factorial(i) | i in 1..n]);

function int: factorial(int: n) =
  let {
    int: f = product([i | i in 1..n]);
  } in
  f
;

% decision variables
array[1..upper_bound] of var 1..n: x;
array[1..num_perms] of var 1..upper_bound: ps; % where start the p'th permutation
var 0..upper_bound: z = max(ps);

% solve minimize z;
% solve :: int_search(x ++ ps, input_order, indomain_split, complete) minimize z;
solve :: int_search(x ++ ps, occurrence, indomain_split, complete) minimize z;

constraint
  forall(perm in 1..num_perms) (
    forall(j in 0..n-1) (
      x[ps[perm]+j] = permutations[perm,j+1]
    )  
  )

  /\ all_different(ps)


  /\ % symmetry breaking
  forall(i in 1..n) (
    x[i] = i
  )


  /\ % palindrome (experimental)
  forall(i in 1..upper_bound) (
    x[i] = x[upper_bound-i+1]
  )
  % forall(i in 1..z+n-1) (
  %   x[i] = x[z+n-1-i+1]
  % )
;

output [
  "factorial(n): \(factorial(n))\n",
  "upper_bound: \(upper_bound)\n",
  "x: \(x)\n",
  "ps: \(ps)\n",
  "z: \(z)\n",
  "tot_len: \(z+n-1)\n",
];

include "globals.mzn"; 

int: n;
set of int: nDomain = 0..n-1;

array[nDomain, nDomain] of var nDomain: quasiGroup;
array[nDomain, nDomain] of var nDomain: quasiGroupColumns;

% solve satisfy;
solve :: int_search([quasiGroup[row, col] | row, col in nDomain], 
        first_fail, indomain_min, complete) satisfy;

constraint

     % assign the "reflected" quasigroup to qGColumns to access its columns
     forall(row,col in nDomain) (
         quasiGroupColumns[col,row] = quasiGroup[row,col]
     )
     /\
     % All rows have to be different
     forall(row in nDomain) (
          all_different([quasiGroup[row, col] | col in nDomain])
     )
     /\
     % All cols have to be different
     forall(col in nDomain) (
          all_different([quasiGroup[row, col] | row in nDomain])
     )
     /\
     % All columns have to be different	       
     forall(col in nDomain) (
          all_different([quasiGroupColumns[row, col] | row in nDomain])
     )
     /\
     % All rows have to be different	       
     forall(row in nDomain) (
          all_different([quasiGroupColumns[row, col] | col in nDomain])
     )
     /\
     % this strange constraint
     % corresponds to:
     % quasiGroup[i, quasiGroup[i,j]] = quasiGroup[quasiGroup[i,j], j]	
     forall(i,j in nDomain) (
         quasiGroup[i, quasiGroup[i,j]] = quasiGroupColumns[j,quasiGroup[i,j]]
     )
     /\
     % Implied constraint: Idempotency
     forall(i in nDomain) (
          quasiGroup[i,i] = i
     )
     /\
     % Symmetry-breaking constraints	
     forall(i in nDomain) (
           quasiGroup[i,n-1] + 2 >= i
     )
;

output 
[ "\nquasiGroupColumns: "
] ++
[
   if col = 0 then "\n" else " " endif ++
    show(quasiGroupColumns[row, col])
  | row, col in nDomain

] ++
[ "\nquasiGroup: "
] ++
[
  if col = 0 then "\n" else " " endif ++
    show(quasiGroup[row, col])
  | row, col in nDomain
] ++ ["\n"];




