model.mzn:
int: nbModel = 3;
int: nbCard = 4;
int: nbRack = 5;

set of int: Models = 0..nbModel-1;
set of int: Cards  = 0..nbCard-1;
set of int: Racks  = 0..nbRack-1;

% modelType:
%   power
%   connectors
%   price
int: modelTypes = 3;
array[Models, 1..modelTypes] of int: model = 
     array2d(Models, 1..modelTypes,
           [  0,  0,   0,
            150,  8, 150,
            200, 16, 200
           ]);

% cardType:
%   power
%   quantity
int: cardTypes = 2;
array[Cards, 1..cardTypes] of int: car = array2d(Cards, 1..cardTypes,
         [  20, 10,
            40,  4 ,
            50,  2, 
            75,  1]);


int: maxPrice = max(r in Models) (model[r,3]);
int: maxCost = nbCard * maxPrice;
array[Models] of int: powerData = array1d(Models, [model[i,1] | i in Models]);
array[Models] of int: connData  = array1d(Models, [model[i,2] | i in Models]);
array[Models] of int: priceData = array1d(Models, [model[i,3] | i in Models]);

% decision variables
array[Racks] of var Models: rack;
array[Racks, Cards] of var 0..nbCard: counters;
var 0..maxCost: cost;


% solve minimize cost;
% solve satisfy;
solve :: int_search(
        rack ++ [counters[r,c] | r in Racks, c in Cards], 
        first_fail, 
        indomain_max, 
        complete) 
    minimize cost;

constraint

   forall(r in Racks) (
      sum(c in Cards) (counters[r,c] * car[c, 1]) <= powerData[rack[r]]
   )
   /\
   forall(r in Racks) (
      sum(c in Cards) (counters[r,c]) <= connData[rack[r]] 
   )
   /\
   forall(c in Cards) (
      sum(r in Racks) ( counters[r,c])  == car[c,2]
   )
   /\
   cost == sum(r in Racks) (priceData[rack[r]])
;   

% for solve satisfy
% constraint cost = 550;

output 
[
  "cost: " ++ show(cost) ++ "\n" ++
  "rack: " ++ show(rack) ++ "\n"
  % ++ "counters: " 
]
% ++
% [ if c = 0 then "\n" else " " endif ++
%     show(counters[r,c]) 
%   | r in Racks, c in  Cards
% ]
;

include "globals.mzn"; 

int: n = 20;
set of 1..n: S = 1..n;
int: num_sets = 2;
array[1..num_sets] of var set of S: a;
array[1..num_sets] of var 0..n*n: sums;
array[1..num_sets] of var 0..n*n*n*n: sum_squared;


%
% set_sum
% sums the elements in the set s
% 
predicate set_sum(var set of int: s, var int: the_sum) =
   the_sum = sum(i in ub(s)) (bool2int(i in s)*i)
;

predicate set_sum_squared(var set of int: s, var int: the_sum) =
   the_sum = sum(i in ub(s)) (bool2int(i in s)*i*i)
;

% solve satisfy;
solve :: set_search(a, first_fail, indomain_min, complete) satisfy;
% solve maximize sums[1];

constraint
  assert(n mod 4 == 0, "n must be a multiple of 4")
;

constraint
   % use all the elements in S and it should be disjoint sets
   partition_set(a, S)
   /\
   forall(i in 1..num_sets) (   
     a[i] `set_sum` sums[i] 
     /\ a[i] `set_sum_squared` sum_squared[i]
   )
   /\
   forall(i in 2..num_sets) (
     card(a[i]) > 0 /\ % this is needed by eclipse
     card(a[i]) = card(a[i-1]) /\
     sums[i] = sums[i-1] 
     /\ sum_squared[i] = sum_squared[i-1] 
   )

  % symmetry breaking
  /\ 1 in a[1]

;

output [
   "a: " ++ show(a) ++ "\n" ++
   "sums: " ++ show(sums) ++ "\n" ++ 
   "sum_squared: " ++ show(sum_squared) ++ "\n" 
];

% For model seeker
