model.mzn:
% Parameters
int: T; % Number of time periods
array[1..T] of int: Demands; % Demand for each time period
array[1..T] of int: UnloadCosts; % Unloading cost for each time period
array[1..T] of int: UnloadCapacity; % Unloading capacity for each time period
int: HoldingCost; % Cost of holding a container
int: MaxContainer; % Maximum number of containers that can be held
int: InitContainer; % Initial number of containers
int: NumCranes; % Number of cranes
int: CraneCapacity; % Capacity of each crane
int: CraneCost; % Cost of each crane

% Decision Variables
array[1..T] of var 0..MaxContainer: Containers; % Number of containers in each time period
array[1..T] of var 0..UnloadCapacity[i]: Unload; % Number of containers unloaded in each time period
array[1..T] of var 0..NumCranes: Cranes; % Number of cranes rented in each time period

% Constraints
constraint Containers[1] = InitContainer + Unload[1] - Demands[1];
constraint forall(i in 2..T) (
    Containers[i] = Containers[i-1] + Unload[i] - Demands[i]
);
constraint forall(i in 1..T) (
    Cranes[i] * CraneCapacity >= Demands[i]
);
constraint forall(i in 1..T) (
    Containers[i] <= MaxContainer
);

% Objective
var int: TotalCost = sum(i in 1..T) (Unload[i] * UnloadCosts[i] + Containers[i] * HoldingCost + Cranes[i] * CraneCost);
solve minimize TotalCost;

% Output
output ["containers_unloaded: ", show(Unload), "\n", "cranes_rented: ", show(Cranes), "\n", "total_cost: ", show(TotalCost)];

data.dzn:
NumMachines = 3;
NumParts = 4;
TimeRequired = [|2, 1, 3, 2|4, 2, 1, 2|6, 2, 1, 2|];
MachineCosts = [160, 10, 15];
Availability = [200, 300, 500];
Prices = [570, 250, 585, 430];
MinBatches = [10, 10, 10, 10];
StandardCost = 20;
OvertimeCost = 30;
OvertimeHour = [400, 400, 300];

model.mzn:
% Define parameters
int: NumMachines;
int: NumParts;
array[1..NumMachines, 1..NumParts] of int: TimeRequired;
array[1..NumMachines] of int: MachineCosts;
array[1..NumMachines] of int: Availability;
array[1..NumParts] of int: Prices;
array[1..NumParts] of int: MinBatches;
int: StandardCost;
int: OvertimeCost;
array[1..NumMachines] of int: OvertimeHour;

% Define decision variables
array[1..NumParts] of var 0..1000: Batches; % Number of batches for each part
array[1..NumMachines] of var 0..1000: MachineHours; % Number of hours for each machine

% Define constraints
constraint forall(m in 2..NumMachines) (
    sum(p in 1..NumParts) (TimeRequired[m,p] * Batches[p]) <= Availability[m]
);

constraint forall(p in 1..NumParts) (
    Batches[p] >= MinBatches[p]
);

constraint MachineHours[1] = sum(p in 1..NumParts) (TimeRequired[1,p] * Batches[p]);

constraint MachineHours[1] <= OvertimeHour[1];

% Define objective function
var int: TotalProfit = sum(p in 1..NumParts) (Prices[p] * Batches[p]) - 
                        sum(m in 1..NumMachines) (MachineCosts[m] * MachineHours[m]) - 
                        StandardCost * min(MachineHours[1], OvertimeHour[1]) - 
                        OvertimeCost * max(0, MachineHours[1] - OvertimeHour[1]);

% Maximize total profit
solve maximize TotalProfit;

% Output
output ["Batches: ", show(Batches), "\n", "TotalProfit: ", show(TotalProfit)];

