model.mzn:
% Parameters
int: M; % Number of months
int: I; % Number of oils
array[1..M, 1..I] of int: buy_price; % Buying price of each oil in each month
int: sell_price; % Selling price of the final product
array[1..I] of bool: is_vegetable; % Whether each oil is vegetable or not
int: max_vegetable_refining_per_month; % Maximum vegetable oil refining capacity per month
int: max_non_vegetable_refining_per_month; % Maximum non-vegetable oil refining capacity per month
int: storage_size; % Maximum storage capacity for each oil
int: storage_cost; % Storage cost per ton per month
int: min_hardness; % Minimum hardness of the final product
int: max_hardness; % Maximum hardness of the final product
array[1..I] of float: hardness; % Hardness of each oil
int: init_amount; % Initial amount of each oil in storage
int: min_usage; % Minimum usage of each oil if it is used
array[1..I, 1..I] of bool: dependencies; % Dependency matrix of oils

% Decision Variables
array[1..M, 1..I] of var 0..storage_size: buy; % Amount of each oil to buy in each month
array[1..M, 1..I] of var 0..storage_size: refine; % Amount of each oil to refine in each month
array[1..M, 1..I] of var 0..storage_size: storage; % Amount of each oil in storage in each month

% Constraints
constraint forall(m in 1..M)(
  sum(i in 1..I)(refine[m, i]) <= sell_price % Total refined oil should not exceed selling price
);

constraint forall(m in 1..M)(
  sum(i in 1..I where is_vegetable[i])(refine[m, i]) <= max_vegetable_refining_per_month % Vegetable oil refining capacity
);

constraint forall(m in 1..M)(
  sum(i in 1..I where not is_vegetable[i])(refine[m, i]) <= max_non_vegetable_refining_per_month % Non-vegetable oil refining capacity
);

constraint forall(m in 1..M, i in 1..I)(
  storage[m, i] <= storage_size % Storage capacity for each oil
);

constraint forall(m in 1..M)(
  sum(i in 1..I)(hardness[i] * refine[m, i]) / sum(i in 1..I)(refine[m, i]) >= min_hardness % Minimum hardness of final product
);

constraint forall(m in 1..M)(
  sum(i in 1..I)(hardness[i] * refine[m, i]) / sum(i in 1..I)(refine[m, i]) <= max_hardness % Maximum hardness of final product
);

constraint forall(m in 1..M, i in 1..I)(
  if refine[m, i] > 0 then refine[m, i] >= min_usage else true endif % Minimum usage of each oil if it is used
);

constraint forall(m in 1..M, i in 1..I, j in 1..I)(
  if dependencies[i, j] then refine[m, i] <= refine[m, j] else true endif % Dependency constraints
);

% Objective
var int: profit = sum(m in 1..M, i in 1..I)(sell_price * refine[m, i] - buy_price[m, i] * buy[m, i] - storage_cost * storage[m, i]);
solve maximize profit;

% Parameters
int: O; % Number of options
int: P; % Number of price points
int: L; % Number of processes
array[1..O] of float: Allocated; % Allocated resources for each option
array[1..P] of float: Price; % Price at each price point
array[1..L, 1..O] of float: Input; % Input required for each option in each process
array[1..L, 1..P] of float: Output; % Output produced for each price point in each process
array[1..L] of float: Cost; % Cost for each process

% Variables
array[1..L] of var 0.0..1000000.0: Execute; % Number of times each process is executed
var 0.0..1000000000.0: Revenue; % Total revenue

% Constraints
constraint forall(i in 1..O)(
    sum(l in 1..L)(Input[l,i]*Execute[l]) <= Allocated[i]
);

constraint forall(l in 1..L)(
    sum(p in 1..P)(Output[l,p]*Price[p]) >= Cost[l]*Execute[l]
);

% Objective
var float: totalRevenue = sum(l in 1..L, p in 1..P)(Output[l,p]*Price[p]*Execute[l]) - sum(l in 1..L)(Cost[l]*Execute[l]);
constraint Revenue = totalRevenue;

% Solve
solve maximize Revenue;

% Output
output ["revenue: ", show(Revenue), "\nexecute: ", show(Execute)];

% Parameters
int: N; % Number of east-west streets
int: W; % Number of north-south streets
array[1..N, 1..W-1] of float: west_time; % Time to cross each east-west street segment
array[1..N-1, 1..W] of float: north_time; % Time to cross each north-south street segment

% Decision Variables
array[1..N, 1..W] of var 0..1: path; % 1 if the delivery person passes through the intersection, 0 otherwise
array[1..N, 1..W-1] of var 0..1: west_path; % 1 if the delivery person goes west at the intersection, 0 otherwise
array[1..N-1, 1..W] of var 0..1: north_path; % 1 if the delivery person goes north at the intersection, 0 otherwise

% Objective
var float: total_time; % Total time taken to deliver the package

% Constraints
constraint forall(i in 1..N, j in 1..W-1) (
    west_path[i,j] = path[i,j] - path[i,j+1]
);

constraint forall(i in 1..N-1, j in 1..W) (
    north_path[i,j] = path[i,j] - path[i+1,j]
);

constraint path[1,1] = 1;
constraint path[N,W] = 1;

constraint forall(i in 1..N, j in 1..W) (
    if i < N then
        path[i,j] = path[i+1,j] + sum(k in 1..j) (west_path[i,k])
    elseif j < W then
        path[i,j] = path[i,j+1] + sum(k in 1..i) (north_path[k,j])
    else
        path[i,j] = 1
    endif
);

% Objective Function
solve minimize total_time = sum(i in 1..N, j in 1..W-1) (west_path[i,j]*west_time[i,j]) + sum(i in 1..N-1, j in 1..W) (north_path[i,j]*north_time[i,j]);

% Output
output ["paths: ", show([(i,j) | i in 1..N, j in 1..W where path[i,j] = 1]), "\n", "total_time: ", show(total_time)];

% Parameters
int: N; % Number of cities
array[1..N, 1..N] of int: Distances; % Distance matrix
int: StartCity; % Starting city

% Decision Variables
array[1..N+1] of var 1..N: visit_order; % Order of cities visited
var int: total_distance; % Total distance travelled

% Constraints
% Start and end at the start city
constraint visit_order[1] = StartCity;
constraint visit_order[N+1] = StartCity;

% Each city is visited exactly once
include "globals.mzn";
constraint alldifferent(visit_order[1..N]);

% Total distance is the sum of the distances between consecutive cities
constraint total_distance = sum(i in 1..N)(Distances[visit_order[i], visit_order[i+1]]);

% Objective
solve minimize total_distance;

% Output
output ["visit_order: ", show(visit_order), "\n", "total_distance: ", show(total_distance)];

% Parameters
int: T; % Number of periods
array[1..T] of int: Deliver; % Units to be delivered each period
int: StorageCost; % Cost per unit per period for storage
int: SwitchCost; % Cost for changing production level

% Decision Variables
array[1..T] of var 0..sum(Deliver): x; % Units produced each period
array[1..T] of var 0..sum(Deliver): inventory; % Units in inventory each period

% Objective
var int: cost; % Total cost

% Constraints
constraint inventory[1] = x[1] - Deliver[1];
constraint forall(i in 2..T) (
    inventory[i] = inventory[i-1] + x[i] - Deliver[i]
);
constraint forall(i in 2..T) (
    cost >= SwitchCost * abs(x[i] - x[i-1])
);
constraint cost >= sum(i in 1..T) (StorageCost * inventory[i]);

% Objective
solve minimize cost;

% Output
output ["x: ", show(x), "\ncost: ", show(cost)];

% Define parameters
int: T = 5; % Number of periods
int: K = 3; % Number of generator types
array[1..T] of int: demand; % Demand for each period
array[1..K] of int: num; % Number of each generator type
array[1..K] of int: minlevel; % Minimum level of each generator type
array[1..K] of int: maxlevel; % Maximum level of each generator type
array[1..K] of int: runcost; % Running cost of each generator type
array[1..K] of float: extracost; % Extra cost of each generator type
array[1..K] of int: startcost; % Start-up cost of each generator type

% Define decision variables
array[1..K, 1..T] of var 0..num: numon; % Number of generators of each type that are on in each period
array[1..K, 1..T] of var minlevel..maxlevel: level; % Level at which each generator type is operated in each period

% Define constraints
constraint forall(k in 1..K, t in 1..T) (
    minlevel[k]*numon[k,t] <= level[k,t] /\ level[k,t] <= maxlevel[k]*numon[k,t]
);
constraint forall(t in 1..T) (
    sum(k in 1..K) (level[k,t]) >= demand[t]
);

% Define objective function
var float: total_cost = sum(k in 1..K, t in 1..T) (
    runcost[k]*numon[k,t] + extracost[k]*(level[k,t] - minlevel[k]*numon[k,t]) + startcost[k]*(numon[k,t] > 0)
);

% Minimize total cost
solve minimize total_cost;

% Output solution
output [ "numon: " ++ show(numon) ];

% Load data from .dzn file
include "globals.mzn";

% Define parameters
array[1..19] of float: y;
array[1..19] of float: x;

% Define decision variables
var float: quadratic;
var float: linear;
var float: constant;
array[1..19] of var float: deviations;

% Define constraints
constraint forall(i in 1..19) (
    deviations[i] = abs(y[i] - (quadratic * (x[i]^2) + linear * x[i] + constant))
);

% Define objective function
var float: total_deviation = sum(deviations);
solve minimize total_deviation;

% Output solution
output ["quadratic: ", show(quadratic), "\n",
        "linear: ", show(linear), "\n",
        "constant: ", show(constant), "\n"];

