model.mzn:
% Define parameters
int: N;
array[1..N] of bool: IsWorkstation;
array[1..N] of int: Price;
array[1..N] of float: DiskDrives;
array[1..N] of int: MemoryBoards;
array[1..N] of int: Demand;
array[1..N] of int: Preorder;
array[1..N] of bool: AltCompatible;
int: MaxCpu;
int: MinDisk;
int: MaxDisk;
int: MinMemory;
int: MaxMemory;
int: DemandGP;
int: DemandWS;
int: AltMemory;

% Define decision variables
array[1..N] of var 0..Demand[i]: NumProduced;
array[1..N] of var 0..MemoryBoards[i]*NumProduced[i]: Total256KBoardsUsed;
array[1..N] of var 0..AltMemory: TotalAltBoardsUsed;
array[1..N] of var 0..DiskDrives[i]*NumProduced[i]: TotalDiskDrivesUsed;

% Define constraints
constraint sum(i in 1..N)(NumProduced[i]) <= MaxCpu;
constraint sum(i in 1..N)(TotalDiskDrivesUsed[i]) >= MinDisk;
constraint sum(i in 1..N)(TotalDiskDrivesUsed[i]) <= MaxDisk;
constraint sum(i in 1..N)(Total256KBoardsUsed[i] + TotalAltBoardsUsed[i]) >= MinMemory;
constraint sum(i in 1..N)(Total256KBoardsUsed[i] + TotalAltBoardsUsed[i]) <= MaxMemory;
constraint sum(i in 1..N where IsWorkstation[i])(NumProduced[i]) <= DemandWS;
constraint sum(i in 1..N where not IsWorkstation[i])(NumProduced[i]) <= DemandGP;
constraint forall(i in 1..N)(NumProduced[i] >= Preorder[i]);
constraint forall(i in 1..N)(TotalAltBoardsUsed[i] <= AltMemory * AltCompatible[i]);

% Define objective function
var int: Profit = sum(i in 1..N)(Price[i] * NumProduced[i]);

% Maximize profit
solve maximize Profit;

% Output
output ["{\"system_output\": ["] ++
        [ "{ \"num_produced\": " ++ show(NumProduced[i]) ++ 
          ", \"total_256K_boards_used\": " ++ show(Total256KBoardsUsed[i]) ++ 
          ", \"total_alt_boards_used\": " ++ show(TotalAltBoardsUsed[i]) ++ 
          ", \"total_disk_drives_used\": " ++ show(TotalDiskDrivesUsed[i]) ++ "}" | i in 1..N] ++
        ["], \"profit\": " ++ show(Profit) ++ "}"];

% Parameters
int: n_mines; % Number of mines
int: n_maxwork; % Maximum number of mines that can be operated in a year
array[1..n_mines] of float: royalty; % Royalty cost for each mine
array[1..n_mines] of float: limit; % Production limit for each mine
array[1..n_mines] of float: quality; % Quality of material from each mine
array[1..5] of float: requiredquality; % Required quality for each year
float: price; % Price per unit of material
float: discount; % Discount rate

% Decision Variables
array[1..n_mines, 1..5] of var 0..1: isoperated; % Whether each mine is operated in each year
array[1..n_mines, 1..5] of var 0.0..limit[1..n_mines]: amount; % Amount of ore produced by each mine in each year

% Constraints
constraint forall(i in 1..5) (
    sum(k in 1..n_mines) (isoperated[k, i]) <= n_maxwork % At most n_maxwork mines can be operated in a year
);

constraint forall(i in 1..5) (
    sum(k in 1..n_mines) (amount[k, i] * quality[k]) = requiredquality[i] * sum(k in 1..n_mines) (amount[k, i]) % The quality of the blended ore must meet the required quality
);

constraint forall(k in 1..n_mines, i in 1..5) (
    amount[k, i] <= limit[k] * isoperated[k, i] % The amount of ore produced by a mine cannot exceed its limit
);

% Objective
var float: profit; % Total profit
constraint profit = sum(i in 1..5) (price * sum(k in 1..n_mines) (amount[k, i]) - sum(k in 1..n_mines) (royalty[k] * isoperated[k, i])) * pow(1 - discount, i - 1);
solve maximize profit;

% Output
output [ if fix(isoperated[k, i]) = 1 then "1" else "0" endif | k in 1..n_mines, i in 1..5] ++ [ "\n" ] ++
       [ show(fix(amount[k, i])) | k in 1..n_mines, i in 1..5];

% Parameters
int: N; % Number of currencies
array[1..N] of float: Start; % Initial amount of each currency
array[1..N] of float: Limit; % Limit of transactions for each currency
array[1..N, 1..N] of float: Rate; % Exchange rates between currencies

% Decision Variables
array[1..N, 1..N] of var 0.0..Limit[N]: Transactions; % Amount of currency i exchanged to currency j

% Objective
var float: FinalAmount = Start[N] + sum(i in 1..N-1) (Transactions[i,N] * Rate[i,N] - Transactions[N,i] / Rate[N,i]);
maximize FinalAmount;

% Constraints
constraint forall(i in 1..N) (
    sum(j in 1..N) (Transactions[i,j] + Transactions[j,i]) <= Limit[i]
);

constraint forall(i in 1..N, j in 1..N) (
    Transactions[i,j] <= Start[i]
);

constraint forall(i in 1..N, j in 1..N) (
    Transactions[i,j] * Rate[i,j] = Transactions[j,i]
);

% Parameters
int: num_years;
set of int: YEARS = 1..num_years;
set of int: MANPOWER = 1..3;

array[MANPOWER, YEARS] of int: requirement;
array[MANPOWER] of int: strength;
array[MANPOWER] of float: lessonewaste;
array[MANPOWER] of float: moreonewaste;
array[MANPOWER] of int: recruit;
array[MANPOWER] of int: costredundancy;
int: num_overman;
array[MANPOWER] of int: costoverman;
int: num_shortwork;
array[MANPOWER] of int: costshort;

% Decision Variables
array[MANPOWER, YEARS] of var 0..recruit[MANPOWER]: recruit_year;
array[MANPOWER, YEARS] of var 0..num_overman: overmanning_year;
array[MANPOWER, YEARS] of var 0..num_shortwork: short_year;

% Constraints
constraint forall(k in MANPOWER, i in YEARS)(
  if i = 1 then
    strength[k] + recruit_year[k,i] - overmanning_year[k,i] - short_year[k,i] = requirement[k,i]
  else
    (1 - moreonewaste[k]) * (strength[k] + sum(j in 1..(i-1))(recruit_year[k,j] - overmanning_year[k,j] - short_year[k,j])) + recruit_year[k,i] - overmanning_year[k,i] - short_year[k,i] = requirement[k,i]
  endif
);

% Objective
var int: total_cost = sum(k in MANPOWER, i in YEARS)(costredundancy[k] * recruit_year[k,i] + costoverman[k] * overmanning_year[k,i] + costshort[k] * short_year[k,i]);
solve minimize total_cost;

% Output
output ["recruit: ", show(recruit_year), "\n", "overmanning: ", show(overmanning_year), "\n", "short: ", show(short_year)];

% Parameters
int: K = 3; % Number of industries
int: T = 5; % Number of years
set of int: INDUSTRIES = 1..K;
set of int: YEARS = 1..T;

% Input data
array[INDUSTRIES, INDUSTRIES] of float: inputone;
array[INDUSTRIES] of float: manpowerone;
array[INDUSTRIES, INDUSTRIES] of float: inputtwo;
array[INDUSTRIES] of float: manpowertwo;
array[INDUSTRIES] of int: stock;
array[INDUSTRIES] of int: capacity;
array[INDUSTRIES] of float: demand;

% Decision variables
array[INDUSTRIES, YEARS] of var 0..capacity[INDUSTRIES]: produce;
array[INDUSTRIES, YEARS] of var 0..capacity[INDUSTRIES]: buildcapa;
array[INDUSTRIES, YEARS] of var 0..capacity[INDUSTRIES]: stockhold;

% Constraints
constraint forall(k in INDUSTRIES, t in YEARS) (
    produce[k, t] + buildcapa[k, t] <= capacity[k]
);

constraint forall(k in INDUSTRIES, t in YEARS) (
    produce[k, t] + stockhold[k, t] >= demand[k]
);

constraint forall(k in INDUSTRIES, t in YEARS diff {1}) (
    stockhold[k, t] = stockhold[k, t-1] + produce[k, t-1] - demand[k]
);

constraint forall(k in INDUSTRIES, t in YEARS diff {1, 2}) (
    capacity[k] = capacity[k] + buildcapa[k, t-2]
);

% Objective function
var float: total_manpower;
constraint total_manpower = sum(k in INDUSTRIES, t in YEARS) (
    produce[k, t]*manpowerone[k] + buildcapa[k, t]*manpowertwo[k]
);
solve maximize total_manpower;

% Define parameters
int: num_industries = 3;
int: num_years = 5;
set of int: Industries = 1..num_industries;
set of int: Years = 1..num_years;

% Input data
array[Industries, Industries] of float: inputone;
array[Industries] of float: manpowerone;
array[Industries, Industries] of float: inputtwo;
array[Industries] of float: manpowertwo;
array[Industries] of float: stock;
array[Industries] of float: capacity;
float: manpower_limit;
array[Industries] of float: demand;

% Decision variables
array[Industries, Years] of var 0.0..manpower_limit: produce;
array[Industries, Years] of var 0.0..manpower_limit: buildcapa;
array[Industries, Years] of var 0.0..manpower_limit: stockhold;

% Constraints
constraint forall(i in Industries, t in Years) (
    produce[i,t] + buildcapa[i,t] <= capacity[i] + if t > 2 then buildcapa[i,t-2] else 0 endif
);

constraint forall(i in Industries, t in Years) (
    produce[i,t] + buildcapa[i,t] + stockhold[i,t] = 
    if t > 1 then stockhold[i,t-1] else stock[i] endif + 
    sum(j in Industries) (produce[j,t] * inputone[j,i])
);

constraint forall(t in Years) (
    sum(i in Industries) (produce[i,t] * manpowerone[i] + buildcapa[i,t] * manpowertwo[i]) <= manpower_limit
);

constraint forall(i in Industries, t in Years) (
    produce[i,t] >= demand[i]
);

% Objective function
var float: total_capacity = sum(i in Industries) (capacity[i] + sum(t in 3..num_years) (buildcapa[i,t]));
solve maximize total_capacity;

% Output
output ["produce: ", show(produce), "\n", "buildcapa: ", show(buildcapa), "\n", "stockhold: ", show(stockhold)];

