model.mzn:
include "globals.mzn";

% Define the size of the board
int: n = 8;

% Define the variables
array[1..n, 1..n] of var 0..2: board;

% Define the number of queens
var 0..n: queens;

% The number of black and white queens must be equal
constraint sum(i in 1..n, j in 1..n)(board[i,j] = 1) = queens;
constraint sum(i in 1..n, j in 1..n)(board[i,j] = 2) = queens;

% No queen is under attack from an opposing queen
constraint forall(i in 1..n, j in 1..n) (
  if board[i,j] = 1 then
    forall(k in (i+1)..n)(board[k,j] != 2) /\
    forall(k in (j+1)..n)(board[i,k] != 2) /\
    forall(k in 1..min(n-i,n-j))(board[i+k,j+k] != 2)
  elseif board[i,j] = 2 then
    forall(k in (i+1)..n)(board[k,j] != 1) /\
    forall(k in (j+1)..n)(board[i,k] != 1) /\
    forall(k in 1..min(n-i,n-j))(board[i+k,j+k] != 1)
  else
    true
  endif
);

% Maximize the number of queens
solve maximize queens;

% Output the solution
output [ if fix(board[i,j]) = 1 then "B" else if fix(board[i,j]) = 2 then "W" else "_" endif endif | i in 1..n, j in 1..n];

include "globals.mzn";

% Define the parameters
int: n; % The number of variables
int: k; % The number of values

% Define the decision variables
array[1..n] of var 1..k: x;

% Define the constraints
constraint forall(i in 1..n-1)(x[i] <= x[i+1]);

% Define the objective function
var int: obj = sum(i in 1..n)(x[i]);

% Define the optimization problem
solve maximize obj;

% Output the solution
output ["x = ", show(x), "\n", "obj = ", show(obj), "\n"];

% Define the data
n = 5;
k = 10;

include "globals.mzn";

% the size of the sequence
int: n;

% the sequence
array[0..n-1] of var 0..n-1: x;

% the interval sequence
array[1..n-1] of var 1..n-1: y;

% each pitch-class occurs exactly once
constraint alldifferent(x);

% the musical intervals between neighboring notes cover the full set of intervals
constraint alldifferent(y);

% calculate the interval sequence
constraint forall(i in 1..n-1)(y[i] = abs(x[i] - x[i-1]));

solve satisfy;

output ["x: " ++ show(x) ++ "\n" ++ "y: " ++ show(y) ++ "\n"];

include "globals.mzn";

% Define the range of numbers
int: n = 8;

% Define the sets A and B
set of int: A = 1..n;
set of int: B = 1..n;

% Define the variables for the elements in sets A and B
array[A] of var 0..1: a;
array[B] of var 0..1: b;

% Define the constraints
constraint forall(i in A)(sum(j in A)(a[j]*j) = sum(j in B)(b[j]*j));
constraint forall(i in A)(sum(j in A)(a[j]*j*j) = sum(j in B)(b[j]*j*j));
constraint sum(i in A)(a[i]) = sum(i in B)(b[i]);

% Ensure that the elements in both sets are different
constraint forall(i in A)(a[i] + b[i] <= 1);

% Solve the problem
solve satisfy;

% Output the solution
output [ "A = ", show([ i | i in A where a[i] = 1 ]), "\n", "B = ", show([ i | i in B where b[i] = 1 ]) ];

include "globals.mzn";

% Size of the sequence
int: n = 10;

% Sequence of integers
array[0..n-1] of var 0..n-1: x;

% Cardinality constraints
constraint forall(i in 0..n-1)(count(x, i, x[i]));

% Sum constraints
constraint sum(x) = n;

solve satisfy;

output ["Magic Sequence: "] ++ [show(x[i]) | i in 0..n-1];

include "globals.mzn";

% Size of the chessboard
int: n = 7;

% Array of variables
array[1..n] of var 0..n-1: queens;

% All elements must be different
constraint alldifferent(queens);

% No two queens are in the same diagonal
constraint forall(i in 1..n)(
  forall(j in i+1..n)(
    abs(queens[i]-queens[j]) != abs(i-j)
  )
);

% Find a solution
solve satisfy;

% Output the solution
output [ "\n" ++ show(queens[i]) | i in 1..n];

include "globals.mzn";

% Order of the quasigroup
int: n = 4;

% Quasigroup
array[1..n, 1..n] of var 1..n: Q;

% Each element occurs once in every row and column
constraint forall(i in 1..n)(alldifferent(row(Q, i)));
constraint forall(i in 1..n)(alldifferent(col(Q, i)));

% Quasigroup properties
constraint forall(a in 1..n, b in 1..n)(Q[Q[a,b], Q[b,a]] = a);
constraint forall(a in 1..n, b in 1..n)(Q[Q[Q[b,a],b],b] = a);
constraint forall(a in 1..n, b in 1..n)(Q[Q[a,b],b] = Q[a, Q[a,b]]);

% Quasigroup is idempotent
constraint forall(a in 1..n)(Q[a,a] = a);

solve satisfy;

output ["Quasigroup:\n"] ++ [show(Q[i,j]) ++ " " | i in 1..n, j in 1..n];

include "globals.mzn";

% Define the variables
var int: n;
var int: c;

% Define the constraint
constraint n + c = 10;

% Define the objective function
solve maximize n;

% Output the solution
output ["n = ", show(n), "\nc = ", show(c)];

include "globals.mzn";

% The given amount of money
int: n = 13;

% The coin denominations
set of int: Coins = 1..n;

% The number of coins of each denomination
array[Coins] of var 0..n: x;

% The objective is to minimize the total number of coins
var int: total = sum(c in Coins) (x[c]);

% The sum of the coins must equal the given amount of money
constraint sum(c in Coins) (c*x[c]) = n;

% The objective is to minimize the total number of coins
solve minimize total;

% Output the solution
output ["The minimum number of coins is: ", show(total), "\n"];

