  "{\n",
  "  \"x\": ", show(x), ",\n",
  "  \"d_x\": ", show(d_x), ",\n",
  "  \"digital_roots\":\n  {\n",
] ++ 
[
   % "digital_roots: ", show(d_roots), "\n"
   "    \"" ++ show(i) ++ "\""++ ": " ++ show(d_roots[i]) ++ ",\n"
   | i in 1..m-1
] ++
[
