include "globals.mzn"; 
int: n = 12;
% int: n = 7; % For the Ruby Quiz example
int: num_families = 4;

array[1..n] of 1..num_families: family = [1,1,1,1, 2, 3,3,3,3,3, 4,4];
% Ruby Quiz example:
% array[1..n] of 1..num_families: family = [1,1,2,2, 3, 4,4];

% decision variables
array[1..n] of var 1..n: x;


% Ensure that there are no fix points in the array.
predicate no_fix_points(array[int] of var int: x) =
  forall(i in index_set(x)) ( 
     x[i] != i
  )
;

solve satisfy;
% solve :: int_search(x, first_fail, indomain_min, complete) satisfy;

constraint
  % Everyone gives and receives a Secret Santa
  all_different(x) 

  /\ % Can't be one own's Secret Santa
  no_fix_points(x) 

  /\ % No Secret Santa to a person in the same family
  forall(i in index_set(x)) (
     family[i] != family[x[i]]
  )
; 


output [
   "Person " ++ show(i) ++ " (family: " ++ show(family[i]) ++ ") is a Secret Santa of " ++ show(x[i]) ++ " (family: " ++ show(family[x[i]]) ++ ")\n"
   | i in 1..n
] ++ 
["\n"];

var 1000..9999: n;
array[1..4] of var 0..9: n_a;
var 1000000..99980001: n_squared;
array[1..8] of var 0..9: n_squared_a;

predicate toNum(array[int] of var int: number, var int: num_sum,  float: base) =
          let { int: len = length(number) }
          in
          num_sum = sum(i in 1..len) (
            ceil(pow(base, int2float(len-i))) * number[i]
          )
          /\ forall(i in 1..len) (number[i] >= 0)
;


solve satisfy;
% solve :: int_search(x, "first_fail", "indomain", "complete") satisfy;

constraint
   % doing it the hard way ...
   toNum(n_a, n, 10.0)
   /\
   toNum(n_squared_a, n_squared, 10.0)
   /\
   forall(i in 5..8) (
      n_a[i-4] = n_squared_a[i]
   )
   /\
   n*n = n_squared
;

output
