include "globals.mzn"; 

% data
% size of grid
int: n;
% number of 1s and 0s in each row
int: m = n div 2;
% initial grid configuration 
array[1..n, 1..n] of var 0..1: problem;

% decision variables
array[1..n, 1..n] of var 0..1: grid;


% satisfaction
solve satisfy;

% initialize the problem
constraint
  forall(i, j in 1..n) (
    grid[i, j] = problem[i, j]
  );

% equal number of 0s and 1s in each row 
constraint
  forall(i in 1..n) (
    sum([bool2int(grid[i, j] = 0) | j in 1..n]) = m
  );

% equal number of 0s and 1s in each column
constraint
  forall(i in 1..n) (
    sum([bool2int(grid[j, i] = 0) | j in 1..n]) = m
  );

% no more than two of the same values adjacent
constraint
  forall(i in 2..n-1) (
    forall(j in 1..n) (
      (grid[i-1, j] != grid[i, j] \/ grid[i, j] != grid[i+1, j])
      /\
      (grid[j, i-1] != grid[j, i] \/ grid[j, i] != grid[j, i+1])
    )
  );

% no identical row
constraint
  forall(i, j in 1..n where i < j) (
    exists(k in 1..n) ( grid[i, k] != grid[j, k] )
  );

% no identical column
constraint
  forall(i, j in 1..n where i < j) (
    exists(k in 1..n) ( grid[k, i] != grid[k, j] )
  );  

% output
output [
   if j = 1 then "\n" else " " endif ++
     show(grid[i,j])
   | i,j in 1..n
];

int: n;
% clues in the grid
array[1..n, 1..n] of -1..9: puzzle;
% solution grid
array[1..n, 1..n] of var 0..1: grid;
% -1 represents a blank
int: X = -1; 

% satisfaction
solve satisfy;

% the number of neighboring painted squares must be equal to the value of the clue for every clue
constraint
    forall(i,j in 1..n) (
      (
       (puzzle[i,j] >= 0)
        ->
        puzzle[i,j] = sum(a,b in {-1,0,1} where 
            i+a > 0  /\ j+b >  0 /\
            i+a <= n /\ j+b <= n
         )
           (grid[i+a,j+b])
      )
    )
;

% output
output [
   if j = 1 then ",\n" else "," endif ++
     show(grid[i,j])
   | i, j in 1..n
]
++
["\n"]
;

include "globals.mzn";

% Number of employees
int: n = 6;

% Office assignments (1-6)
array[1..n] of var 1..6: offices;

% Employees
enum EMPLOYEE = {Arthur, Bella, Craig, Duncan, Elizabeth, Francesca};

% Define the office positions for clarity
var 1..6: Arthur_office = offices[1];
var 1..6: Bella_office = offices[2];
var 1..6: Craig_office = offices[3];
var 1..6: Duncan_office = offices[4];
var 1..6: Elizabeth_office = offices[5];
var 1..6: Francesca_office = offices[6];

% Constraints
% Arthur is directly above Bella
constraint Arthur_office == Bella_office + 3;

% Bella works next to Duncan
constraint abs(Bella_office - Duncan_office) == 1;

% % Elizabeth’s office number is smaller than Francesca’s
constraint Elizabeth_office < Francesca_office;

% Craig and Francesca are in adjacent rooms
constraint abs(Craig_office - Francesca_office) == 1;

% ensure all offices are unique
constraint alldifferent(offices);

% satisfaction
solve satisfy;

% output
output ["Arthur: ", show(Arthur_office), "\n",
        "Bella: ", show(Bella_office), "\n",
        "Craig: ", show(Craig_office), "\n",
        "Duncan: ", show(Duncan_office), "\n",
        "Elizabeth: ", show(Elizabeth_office), "\n",
        "Francesca: ", show(Francesca_office), "\n"];

include "globals.mzn"; 

int: total = 77;
var 1..total: a;
var 1..total: b;
var 1..total: c;

var 1..total: y;


solve satisfy;
% solve :: int_search(x, first_fail, indomain_min, complete) satisfy;

constraint
    b*a + b*b + (a+b)*c = total 
    /\ y = a + 2*b + c
    /\ y > 0
    /\ a > 0
    /\ b > 0
    /\ c > 0
;

output ["y=\(y)"]; % this only show a single solution: y=18

int: n = 5;

var 10000..99999: p;
array[1..n] of var 0..9: x;


predicate is_prime(var int: x) =
   x > 1 
   /\
   forall(i in 2..1+ceil(sqrt(int2float(ub(x))))) ( 
        (i < x) -> (x mod i > 0)
   )
;

% channel array a <-> var int n
predicate toNum10(array[int] of var int: a, var int: n) =
          let { int: len = length(a) }
          in
          n = sum(i in 1..len) (
            ceil(pow(10.0, int2float(len-i))) * a[i]
          )
          /\ forall(i in 1..len) (a[i] >= 0)
;


% solve satisfy;
solve :: int_search(x, first_fail, indomain_min, complete) satisfy;

constraint
   is_prime(p) /\ toNum10(x, p)
;

% """
% A limerick prime has to have the form AABBA where A is an 
% odd digit and B is any digit other than A. 
% """
constraint
   x[1] mod 2 = 1
   /\ % AA..A
   x[1] = x[2] /\ x[1] = x[5]
   /\ % ..BB.
   x[3] = x[4]
   /\ 
   x[1] != x[3]
;

output [
  "p: " ++ show(p) ++ "\n" ++
  "x: " ++ show(x)
]
 ++ ["\n"]
;

include "globals.mzn"; 

int: n = 8;
set of int: Digits = 0..9;
var Digits: T;
var Digits: O;
var Digits: M;
var Digits: D;
var Digits: A;
var Digits: L;
var Digits: E;
var Digits: Y;

array[1..n] of var Digits: x = [T,O,M,D,A,L,E,Y];
var 10000..99999: DALEY;
var 100..999: TOM = 100*T + 10*O + M;

% convert array <-> number
predicate toNum(array[int] of var int: a, var int: n) =
          let { int: len = length(a) } in
          n = sum(i in 1..len) (
            ceil(pow(10.0, int2float(len-i))) * a[i]
          )
          /\ forall(i in 1..len) (a[i] >= 0)
;


% solve satisfy;
solve :: int_search(x, first_fail, indomain_min, complete) satisfy;

constraint
   all_different(x) /\
   T > 0 /\ D > 0 /\
   toNum([D,A,L,E,Y], DALEY) /\
   TOM * 13 = DALEY
;


output
[
  "x: " ++ show(x) ++ "\n" ++
  "DALEY: " ++ show(DALEY)
];

data.dzn:
% Data from
% Mike Trick: "Operations Research, Sudoko, Rogo, and Puzzles"
% http://mat.tepper.cmu.edu/blog/?p=1302
%
% LazyFD gives the following solution in 1.1 second:
%
% points = [0, 1, 0, 0, 2, 0, 0, 2, 0, 0, 3, 0]);
% sum_points = 8;
% x = [2, 2, 3, 4, 5, 5, 5, 4, 3, 3, 2, 2]);
% y = [4, 5, 5, 5, 5, 4, 3, 3, 3, 2, 2, 3]);
% 
% Which is correct, though not exactly the same as the 
% one at Mike Tricks blog post:
% Instead of turning from 4,3 -> 4,2 -> 3,2
% this takes              4,3 -> 3,3 -> 3,2
% 
% This has 48 solutions with symmetries;
% 4 when the path symmetry is removed.
rows = 5;
cols = 9;
max_steps = 12;
best = 8;
problem = array2d(1..rows, 1..cols, 
[
  2, W, W, W, W, W, W, W, W,
  W, 3, W, W, 1, W, W, 2, W,
  W, W, W, W, W, W, B, W, 2,
  W, W, 2, B, W, W, W, W, W,
  W, W, W, W, 2, W, W, 1, W,%
]);

model.mzn:
include "globals.mzn"; 

int: n = 4;
set of int: r = 1..4;

var r: ecru_espadrilles;
var r: fuchsia_flats;
var r: purple_pumps;
var r: suede_sandals;

var r: Foot_Farm;
var r: Heels_in_a_Handcart;
var r: The_Shoe_Palace;
var r: Tootsies;

array[1..n] of var r: shoes = [ecru_espadrilles, fuchsia_flats, purple_pumps, suede_sandals];
array[1..n] of var r: shops = [Foot_Farm, Heels_in_a_Handcart, The_Shoe_Palace, Tootsies];



solve satisfy;
% solve :: int_search(x, "first_fail", "indomain", "complete") satisfy;

constraint
  all_different(shoes)
  /\
  all_different(shops)

  /\ % 1. Harriet bought fuchsia flats at Heels in a Handcart.
  fuchsia_flats = Heels_in_a_Handcart

  /\  %  2. The store she visited just after buying her purple pumps was not Tootsies.
  purple_pumps + 1 != Tootsies

  /\ %  3. The Foot Farm was Harriet's second stop.
  Foot_Farm = 2

  /\ %  4. Two stops after leaving The Shoe Place, Harriet bought her suede sandals.
  The_Shoe_Palace + 2 = suede_sandals

;

output [
  "shoes [ecru_espadrilles, fuchsia_flats, purple_pumps, suede_sandals] ", show(shoes),"\n",
  "shops [Foot_Farm, Heels_in_a_Handcart, The_Shoe_Palace, Tootsies]", show(shops),"\n",

];

include "globals.mzn"; 

int: n;
array[1..n, 1..n] of var 1..n: x;
array[1..n, 1..n*2] of 1..n: streams;
int: num_placed;
array[1..num_placed, 1..3] of 1..n: placed;


solve satisfy;

constraint
   %
   % latin square
   % 
   forall(i in 1..n) (
       all_different([ x[i, j] | j in 1..n]) /\
       all_different([ x[j, i] | j in 1..n])
   )
   /\
   % streams
   forall(i in 1..n) (
      all_different([x[streams[i,2*j+1],streams[i,2*j+2]] | j in 0..n-1])
   )
   /\ % placed
   forall(i in 1..num_placed) (
       x[placed[i,1], placed[i,2]] = placed[i,3]
   )

;

output
[ if j = 1 then "\n" else " " endif ++
     show(x[i,j])
  | i,j in 1..n
];

%
% data
%

% data is in the strimko_*.dzn files

% Strimko Set 068
% n = 4;
% streams = array2d(1..n, 1..n*2, [
%                     1,1, 2,2, 3,3, 4,4,
%                     2,1, 1,2, 1,3, 2,4,
%                     3,1, 4,2, 4,3, 3,4,
%                     4,1, 3,2, 2,3, 1,4
%                    ]);

% num_placed = 3;
% placed = array2d(1..num_placed, 1..3, [
%                              2,2,3,
%                              2,3,2,
%                              3,3,1
%                            ]);

include "globals.mzn"; 

int: n;
int: num_digits_all;
int: num_digits_missing;
int: max_len; % max length of a number

% ordered list of all digits of the concatenated numbers 1..n.
array[1..num_digits_all] of int: digits_all; 
int: sum_all = sum(digits_all);

% (random) list of concatenated numbers 1..n where one number is missing
array[1..num_digits_missing] of int: digits_missing; 
int: sum_missing = sum(digits_missing);

% digit sum of the missing number
int: diff_digit_sum = sum_all - sum_missing;
% length of the missing number
int: diff_len = num_digits_all - num_digits_missing;

% decision variables

% number assigned to each position, where a m-length number get m places
% in the list
array[1..num_digits_all] of var 1..n: x;

% start positions of each number
array[1..n] of var 1..num_digits_all: start_pos;

% The domain of the missing number
set of int: missing_domain = { i | i in 1..n where digit_sum(i) = diff_digit_sum /\ digit_length(i) == diff_len };
var 1..n: missing;

% missing number as an array
array[1..max_len] of var 0..9: missing_a;

%
% functions
%
% the length of a number. Note that we have to use m+1 in the parameter to log10/1
function int: digit_length(int: m) = 
   ceil(log10(m+1))
;

% the digits of a number
function array[int] of int: digits(int: m) =
     let {
       int: len = digit_length(m);
       array[1..len] of int: a = [(m mod pow(10,len-i+1)) div pow(10,len-i) | i in 1..len ];
     } in 
     a
;

% digit sum of a number (not reduced!)
function int: digit_sum(int: m) =
     let {
       int: len = digit_length(m);
       int: ds = m - sum([9*(m div pow(10,len-i+1)) | i in 1..len])
     } in 
     ds
;

% alternative variant
function int: digit_sum1(int: m) =
   sum(digits(m))
;


% convert a number <-> array.
% Note: There might be leading zeros in the array.
%
% n = to_num_base(a, base)
function var int: to_num_base(array[int] of var int: a, int: base) =
          let { int: len = card(index_set(a));
                var int: n = sum(i in index_set(a)) (
                   pow(base, len-i) * a[i] 
                 );
         } in n
;

% n = to_num(a) ( base 10)
function var int: to_num(array[int] of var int: a) = to_num_base(a, 10);


% solve satisfy;
solve :: int_search(x, first_fail, indomain_min, complete) satisfy;

constraint
 % just to show the complexity of the problem 
 trace("missing_domain: \(missing_domain)\n") /\

 % digit sum of the missing number:
 %   difference between sum of all digits of numbers 1..n and the digit sum of missing digits
 missing = to_num(missing_a)
 /\
 diff_digit_sum = sum(missing_a)
 /\ % start positions are distinct
 all_different(start_pos)
 /\
 % loop through all the number 1..n and see if there is a place where they can fit.
 % For the missing number we don't try to find any place to fit, but place it last in 
 % the x array
 forall(i in 1..n) ( 
     let {
        int: len = digit_length(i);
        array[int] of 0..9: s = digits(i);
        var 1..num_digits_all: p;
     } in

     if missing != i then
        % Not the missing number: Check for its place
        forall(j in 0..len-1) (
           digits_missing[p+j] = s[j+1] 
           /\
           x[p+j] = i 
           /\
           start_pos[i] = p
        )
     else
       % The missing number. Check for proper digit sum and length
       digit_sum(i) = diff_digit_sum
       /\
       len = diff_len
       /\
       forall(j in 0..len-1) (
           x[p+j] = i 
           /\
           start_pos[i] = p
       )
     endif
  )  
  % special care for the missing number
  /\ % place it last in the solution array and the position array
  forall(i in num_digits_missing+1..num_digits_all) (
     x[i] = missing 
  )
  /\
  start_pos[missing] = num_digits_missing+1
;

constraint
  forall(i in 1..n) (
     count(x,i,digit_length(i))
  )
;

output [
  "missing_domain: \(missing_domain)\n",
  "missing: \(missing)\n",
  "digits_missing: \(digits_missing)\n",
  % "x: \(x)\n",
  % "start_pos: \(start_pos)\n",
]
++
[ "solution:\n" ]
++
[
  if fix(x[i]) != fix(x[i+1]) then 
    show(x[i]) ++ ","
  else 
    ""
  endif ++
  if i = num_digits_all then
    " (," ++ show(missing) ++ ")"
  else "" endif
  | i in 1..num_digits_all
]
;

%
% data
%

% % 1..50
% n = 50;
% max_len = 2;
% num_digits_all = 91;
% digits_all = [1,2,3,4,5,6,7,8,9,1,0,1,1,1,2,1,3,1,4,1,5,1,6,1,7,1,8,1,9,2,0,2,1,2,2,2,3,2,4,2,5,2,6,2,7,2,8,2,9,3,0,3,1,3,2,3,3,3,4,3,5,3,6,3,7,3,8,3,9,4,0,4,1,4,2,4,3,4,4,4,5,4,6,4,7,4,8,4,9,5,0];
