%   
% digits_missing = [1,2,3,4,5,6,7,8,9,1,0,1,1,1,2,1,3,1,4,1,5,1,6,1,7,1,8,1,9,2,0,2,1,2,2,2,3,2,4,2,5,2,6,2,7,2,8,2,9,3,0,3,1,3,2,3,3,3,4,3,5,3,6,3,7,3,8,3,9,4,0,4,1,4,2,4,3,4,4,4,5,4,6,4,7,4,8,5,0]; % 49 missing (21 solutions)
% digits_missing = [1,2,3,4,5,6,7,8,9,1,0,1,1,1,2,1,3,1,4,1,5,1,6,1,7,1,8,1,9,2,0,2,2,2,3,2,4,2,5,2,6,2,7,2,8,2,9,3,0,3,1,3,2,3,3,3,4,3,5,3,6,3,7,3,8,3,9,4,0,4,1,4,2,4,3,4,4,4,5,4,6,4,7,4,8,4,9,5,0]; % 21 missing (21 solutions)
% digits_missing = [1,2,3,4,5,6,7,8,9,1,0,1,1,1,2,1,3,1,4,1,5,1,6,1,7,1,8,1,9,2,1,2,2,2,3,2,4,2,5,2,6,2,7,2,8,2,9,3,0,3,1,3,2,3,3,3,4,3,5,3,6,3,7,3,8,3,9,4,0,4,1,4,2,4,3,4,4,4,5,4,6,4,7,4,8,4,9,5,0]; % 20 missing, 21 solutions

% digits_missing = [1,2,3,4,5,6,7,8,9,1,0,1,1,1,2,1,3,1,4,1,5,1,6,1,7,1,8,2,0,2,1,2,2,2,3,2,4,2,5,2,6,2,7,2,8,2,9,3,0,3,1,3,2,3,3,3,4,3,5,3,6,3,7,3,8,3,9,4,0,4,1,4,2,4,3,4,4,4,5,4,6,4,7,4,8,4,9,5,0]; % 19 missing (21 solutions)
% digits_missing = [1,2,3,4,5,6,7,8,9,1,0,1,1,1,3,1,4,1,5,1,6,1,7,1,8,1,9,2,0,2,1,2,2,2,3,2,4,2,5,2,6,2,7,2,8,2,9,3,0,3,1,3,2,3,3,3,4,3,5,3,6,3,7,3,8,3,9,4,0,4,1,4,2,4,3,4,4,4,5,4,6,4,7,4,8,4,9,5,0]; % 12 missing (sols 12 and 21)

include "globals.mzn"; 

% use letters for a readable representation 
int: n = 10;
int: m = n div 2;
array[1..m] of int: bases = [ceil(pow(10.0,int2float(m-i))) | i in 1..m];

% decision variables
set of int: digits = 0..9; % declare the range 
var digits: A;
var digits: B;
var digits: C;
var digits: D;
var digits: E;

var digits: F;
var digits: G;
var digits: H;
var digits: I;
var digits: J;

% and using an array for the all_different predicate
array[1..n] of var digits: FD =  [A, B, C, D, E, F, G, H, I, J];

var int: X;
var int: Y;
var int: difference = X - Y;


%
% scalar_product(a1, a2, result)
% - a1, a2: two arrays of equal lengths
% - result: the result of summing the product of a1[i]*a2[i]
% 
predicate scalar_product(array[int] of var int: arr1, array[int] of var int: arr2, var int: result) =
          assert(card(index_set(arr1)) == card(index_set(arr2)), 
            "scalar_product: arr1 and arr2 must be of same length.",
             result = sum(i in index_set(arr1)) (
                arr1[i] * arr2[i]
             )
          )
;

constraint
      % more general model
      scalar_product(bases, [A,B,C,D,E], X) /\
      scalar_product(bases, [F,G,H,I,J], Y) /\

      % Instead of using scalar_product, it could be modelled instead as:
      % X = (10000*A +1000*B +100*C +10*D + E) /\
      % Y = (10000*F +1000*G +100*H +10*I + J) /\

      % all number must be equal
      all_different(FD) /\

      % the difference must be positive
      % difference = X - Y /\
      difference > 0
; 



% solve minimize difference;

% this solve hint makes it somewhat faster
solve :: int_search(FD, max_regret, indomain_min, complete) minimize difference;


% result
output [
  show(FD) ++ "\n" ++
  show(X) ++ " - " ++ show(Y) ++ " = " ++ show(difference) ++ "\n"
];

