    L18 < L19 /\  L19 < L20 /\  L20 < L21 /\  L21 < L22 /\  L22 < L23 /\  
    L23 < L24 /\  L24 < L25 /\ 

    % Sum of Squares Constraint
    L1*L1 + L2*L2 + L3*L3 + L4*L4 + L5*L5 + L6*L6 + L7*L7 + L8*L8 + 
    L9*L9 + L10*L10 + L11*L11 + L12*L12 + L13*L13 + L14*L14 + L15*L15 + 
