    L23*L23 + L24*L24 = L25*L25 /\ 

    % Length Constraints
    L1 + L3 = L4 /\  L4 + L1 = L5 /\ 
    L4 + L5 = L7 /\  L5 + L7 = L8 /\ 
    L3 + L4 + L7 = L9 /\  L1 + L5 + L8 = L11 /\ 
    L2 + L12 = L14 /\  L2 + L14 = L15 /\ 
    L2 + L15 = L16 /\  L10 + L11 = L17 /\ 
    L7 + L8 + L9 = L18 /\  L6 + L16 = L19 /\ 
