    L13 + L20 = L24 /\  L21 + L22 + L23 = L25 /\ 
    L18 + L21 + L24 = L25 /\  L19 + L20 + L24 = L25 /\ 
    L15 + L16 + L19 + L23 = L25 /\ 

    % Double check the Answer
    LHS = L1*L1 + L2*L2 + L3*L3 + L4*L4 + L5*L5 + L6*L6 + L7*L7 + 
    L8*L8 + L9*L9 + L10*L10 + L11*L11 + L12*L12 + L13*L13 + L14*L14 + 
    L15*L15 + L16*L16 + L17*L17 + L18*L18 + L19*L19 + L20*L20 + L21*L21 + 
    L22*L22 + L23*L23 + L24*L24 /\ 

    RHS = L25*L25

;

output [
  "LD: ", show(LD),"\n",
  "LHS: ", show(LHS), "\n",
  "RHS: ", show(RHS), "\n",

];

include "globals.mzn"; 

int: n = 7;
int: max_val = 100;

% decision variables
array[1..n] of var 1..max_val: x;
var 1..max_val*n: z;



% solve satisfy;
solve :: int_search(x, max_regret, indomain_min, complete) satisfy;

constraint
  alldifferent(x) /\

  % ordered
  increasing(x) /\

  z = sum(x) /\

  z mod n = 0 /\

  forall(i,j in 1..n where i < j) (
    %  abs(x[i]-x[j]) > 1 /\ % extra: not allowing differences of 1.
    z mod abs(x[i]-x[j]) = 0
  )
;

output
[
  "x: " ++ show(x) ++ "\n" ++
  "z: " ++ show(z) ++ "\n" 
];

input.json:
{
