model.mzn:
int: m = 4;
int: n = 4; 
% int: m = 5;
% int: n = 5; % 

int: m3 = m mod 3;
int: n3 = n mod 3;

set of 1..m: M = 1..m;
set of 1..n: N = 1..n;
set of 1..p: P = 1..p;

array[M,N,P] of var 0..1: x;

% compute required number of dominoes
int: p = 
if m3*n3 = 0 then
   (m*n) div 3
elseif m3==n3 then
    (m*n+2) div 3
else
  (m*n+1) div 3
endif
;

% the output matrix
array[M,N] of var 0..n*m: rt;

var int: sum_zeros = sum(i in M, j in M) (bool2int(rt[i,j] = 0));
% var int: z = sum(k in P) (d[k]);

% solve :: int_search([x[i,j,k] | i in M, j in N, k in P], first_fail, indomain_min, complete) maximize sum_zeros;
solve :: int_search([x[i,j,k] | i in M, j in N, k in P], first_fail, indomain_min, complete) satisfy;

constraint
  sum_zeros >= 4
  /\
  % each domino in adjacent cells 
  forall(i in M,j in N,k in P) (
        sum(l in j-1..j+1 where l >= 1 /\ l <= n /\ l != j) (x[i,l,k]) +
        sum(l in i-1..i+1 where l >= 1 /\ l <= m /\ l != i) (x[l,j,k]) >= x[i,j,k]
  )

  /\
  %  each domino covers two cells 
  forall(k in P) (
    sum(i in M,j in N) (x[i,j,k]) = 2
  )
  /\
  % each cell covered by, at most, one domino 
  forall(i in M,j in N) (
      sum(k in P) (x[i,j,k]) <= 1
  )
  /\
  % no two adjacent cells vacant (rows) 
  forall(i in M,j in 1..n-1) (
    sum(c in j..j+1,k in P) (x[i,c,k]) >= 1
  )
  /\
  % no two adjacent cells vacant (columns)
  forall(i in 1..m-1,j in N) (
    sum(r in i..i+1,k in P) (x[r,j,k]) >= 1
  )
  /\ % for the output
  forall(i in M) (
    forall(j in N) (
      rt[i,j] = sum(k in P) (k*x[i,j,k])
    )
  )
;


output 
[
  "sum_zeros: " ++ show(sum_zeros)
] ++
[
  if j = 1 then "\n" else " " endif ++
    show(rt[i,j])
  | i in M, j in N
] ++ ["\n"];

int: n = 6;

% indices
set of int: N = 1..n;
set of int: M = 1..n-1;

% variables
array[N, N, M] of var 0..1: x; % x[i,j,k] = 1 if number on tank {i,j} = k
array[N, N] of var int: res; % the output result

solve :: int_search([x[i,j,k] | i, j in N, k in M], first_fail, indomain_min, complete) satisfy;
% solve :: int_search([res[i,j] | i, j in N], first_fail, indomain_min, complete) satisfy;

constraint

  % attacks on tank = number on tank
  forall(i in N,j in N) (
    (
     sum(p in N where p != j) ( x[i,p,abs(j-p)]) + 
     sum(q in N where q != i) (x[q,j,abs(i-q)])
    ) = sum(k in M) (k*x[i,j,k])
  )

  /\  % one number on each tank
  forall(i in N,j in N) (
    sum(k in M) (x[i,j,k]) = 1
  )

  /\ % symmetry constraints - otherwise too slow
  forall(i in N,j in N,k in M) (
      x[i,j,k] = x[(n+1-i),(n+1-j),k]
  )
  /\
  forall(i in N,j in N,k in M) (
    x[i,j,k] = x[j,(n+1-i),k]
  )

  /\ % for the output
  forall(i, j in N) (
     res[i,j] = sum(k in 1..n-1) (k*x[i,j,k])
  )
;

output [
   if j = 1 then "\n" else " " endif ++
     show(res[i,j])
   | i,j in N
] ++ ["\n"];

int: n;
int: color;

set of 1..n: N = 1..n;
set of 1..n*n: P = 1..n*n;   % pieces and positions
set of 1..3: S = 1..3;     % spots and orientations

array[N] of int: right;
array[N] of int: left;
array[N] of int: base;
array[P,S,S] of int: piece_col;

array[P,P,S] of var 0..1: x;
array[P,S] of var int: y;

solve satisfy;

constraint
  forall(i in P, j in S) (
     y[i,j] >= 0
  )
  /\  
  % each position occupied by one triangle in one orientation
  forall(j in P) (
    sum(i in P, k in S) (x[i,j,k]) = 1
  )
  /\
  % each triangle in one position and one orientation
  forall(i in P) (
    sum(j in P, k in S) (x[i,j,k]) = 1
  )
  /\
  % spot colours consistent with piece positions and orientations  
  forall(i in P, j in P, k in S, m in S) (
    y[j,m] >= piece_col[i,k,m] - color*(1-x[i,j,k]) /\
    y[j,m] <= piece_col[i,k,m] + color*(1-x[i,j,k])
  )
  /\
  % color matches (outer)
  forall(i in N) (
    y[(i-1)*(i-1)+1,1] = left[i] /\
    y[i*i,2] = right[i] /\
    y[(n-1)*(n-1)+2*(i-1)+1,3] = base[i] 
  )
  /\
  % color matches (inner)
  forall(i in 1..n-1,j in 1..i) (
    y[-2*i+2*j+i*i,3] = y[2*j+i*i,1] /\
    y[-8*i+6*j+i*i+j*j-2*i*j+16,2] = y[-8*i+6*j+i*i+j*j-2*i*j+17,3] /\
    y[-8*i+6*j+i*i+j*j-2*i*j+17,2] = y[-8*i+6*j+i*i+j*j-2*i*j+18,1]
  )

;

n = 4;
color = 6;
left = [2,2,3,2];
right = [6,3,1,3];
base = [5,2,1,4];

% color code: 1 - red, 2 - green, 3 - white, 4 - blue, 5 - black, 6 - yellow
% each row describes a triangle in each of three possible orientations

piece_col =   
array3d(P,S,S,
[1,2,3,3,1,2,2,3,1,
 1,2,5,5,1,2,2,5,1,
 1,2,6,6,1,2,2,6,1,
 1,3,6,6,1,3,3,6,1,
 1,5,2,2,1,5,5,2,1,
 1,5,2,2,1,5,5,2,1,
 2,4,6,6,2,4,4,6,2,
 2,5,5,5,2,5,5,5,2,
 2,5,6,6,2,5,5,6,2,
 2,6,3,3,2,6,6,3,2,
 2,6,3,3,2,6,6,3,2,
 3,3,4,4,3,3,3,4,3,
 3,4,4,4,3,4,4,4,3,
 3,4,5,5,3,4,4,5,3,
 3,4,5,5,3,4,4,5,3,
 4,6,5,5,4,6,6,5,4
 ])
;


output [
  if j = 1 then "\n" else " " endif ++
  show(y[i,j])
  | i in P, j in S
] ++ ["\n"];

int: heap = 5; 

% columns for binary representation of position after move
int: col = 4;  

% maximum number of heaps to change (if k>1 then Moore's game) ! number of squares per side
int: k = 1; 

% maximum number allowed in any heap
int: nmax = ceil(pow(2.0,int2float(col-1)));

% number in each heap before move;
array[1..heap] of var int: n; 


% variables
% binary values of position after move
array[1..heap, 1..col] of var 0..1: x ; 

% 1 if heap changed, 0 otherwise
array[1..heap] of var 0..1: d; 

% number taken from heap
array[1..heap] of var int: s; 

% number in each heap after move
array[1..heap] of var int: m;

% dummy variables for winning position test 
array[1..col] of var int: w; 

% number of heaps changed
var int: heapch = sum(i in 1..heap) (d[i]);

% minimise number of heaps changed - 
% if solution is zero then current position already safe
solve minimize heapch;


constraint
  forall(i in 1..heap) (
     s[i] >= 0
     /\
     m[i] >= 0
  )
  /\
  forall(i in 1..col) (
     w[i] >= 0
  )

  /\ % convert heap numbers [after move] to binary
  forall(i in 1..heap) (
     sum(j in 1..col) ( ceil(pow(2.0, int2float((j-1))))*x[i,j]  ) = m[i]
  )

  /\ % ensures safe position after move
   forall(j in 1..col) (
        sum(i in 1..heap) (x[i,j]) = (k+1)*w[j]
   )

   /\ % positions before and after are consistent with move
  forall(i in 1..heap) (
    n[i]-s[i] = m[i]
  )

  /\ % dummy set to 1 if heap changed
  forall(i in 1..heap) (
    s[i]-nmax*d[i] <= 0
  )
;

%output [
% "heapch: ", show(heapch), "\n",
% "d: ", show(d), "\n",
% "m: ", show(m), "\n",
% "s: ", show(s), "\n",
% "w: ", show(w), "\n",
%
%];

output [
  show(s[i]) ++ " " ++ show(m[i]) ++ "\n"
  | i in 1..heap
];

