% solve satisfy;
solve :: float_search(item,0.01, input_order, indomain_split) satisfy;

output [
   show(item), "\n",
];

var int: L; % >= 0;
var int: w; % >= 0;
var int: h; % >= 0;

var int: wh = w*h;

solve maximize wh;
% solve satisfy;

constraint
  L >= 0 /\ w >= 0 /\ h >= 0 /\
  wh >= 625 /\
  L >= 0 /\ w >= 0 /\ h >= 0 /\
  2*(w+h) = L /\
  L <= 100 /\
  h >= 2
;


output 
[
  show([L,w,h,wh]), "\n",
  "[w,h,L/4]: ", show([w,h,L div 4])
];

float: v = pow(10.0,8.0);

var -v..v: x;
var -v..v: y;


% solve satisfy;
solve :: float_search([x,y], 0.00000000000001, input_order, indomain_split, complete) satisfy;

constraint
   x*x + y*y = 1.0 
   /\
   x*x = y

;

output [
  "x:" ++ show_float(3,12,x) ++ "\n" ++
  "y:" ++ show_float(3,12,y)
];

int: T = 3; % time period

% comment one of the initiations to calculate it:
var 0.0..10000.0: I = 10.0/100.0;
var 0.0..10000.0: R = 150.0; 
var 0.0..10000.0: P; % = 373.02779864763318;

array[1..T] of var float: mortgage;

% solve satisfy;
% solve :: float_search(mortgage, 0.00000001, input_order, indomain_split, complete) satisfy;
solve minimize P;

constraint
   forall(i in 1..T) ( mortgage[i] >= 0.0) /\

   % start value:
   mortgage[1] = P + (P  * I) - R /\
   forall(i in 2..T) (
     % calculate the next value using a local variable
     % This is the recursion in the CLP example.
     % let {
     %    var float: NP = mortgage[i-1] + (mortgage[i-1]  * I) - R 
     % }
     % in
     % in
     % mortgage[i] =  NP /\ NP >= 0.0
     % [Later note: This is simpler. :-)]
     mortgage[i] = mortgage[i-1] + (mortgage[i-1]  * I) - R
   )
;

output [
   "P: ", show(P), "\n",
   "I: ", show(I), "\n",
   "R: ", show(R), "\n",
   "mortgage: ", show(mortgage),"\n", % is not especially interesting
];

include "globals.mzn";

set of int: xrange = 1..99;
var xrange: A;
var xrange: B;
var xrange: C;
var xrange: D;
var xrange: E;
var xrange: F;
var xrange: G;
var xrange: H;
var xrange: I;
% var xrange: J;
var xrange: K;
array[1..10] of var xrange: LD = [A,B,C,D,E,F,G,H,I,K];

% Predicate to simplify the constraint section
predicate s(var int: X1, var int: X2, var int: Y1, var int: Y2 ) =
   X1*X1 + X2*X2  = Y1*Y1 + Y2*Y2
;

% solve satisfy;
solve :: int_search(LD, first_fail, indomain_min, complete) satisfy;


constraint
   all_different(LD) /\
   A = 16 /\
   B = 2 /\
   F = 8 /\
   G = 14 /\

   s(A, B, F, G) /\
   s(B, C, G, H) /\
   s(C, D, H, I) /\
   s(D, E, I, K) /\
   s(E, F, K, A)
;


output [
   show(LD), "\n",
];

