var int: roads;
var int: total_investment;

constraint total_investment = housing + roads;
constraint total_investment <= 3500;
constraint housing >= 750;
constraint roads >= 0.24 * total_investment;

var float: profit;

constraint profit = 0.95 * housing + 0.32 * roads;

solve maximize profit;

include "globals.mzn";

% number of packages of seafood medley one
var int: medley_one;
% number of packages of seafood medley two
var int: medley_two;

% number of packages are non-negative
constraint medley_one >= 0;
constraint medley_two >= 0;

% number of available scallops is 10000 grams
% medley one contains 20 grams of scallops and medley two contains 40 grams of scallops
constraint 20 * medley_one + 40 * medley_two <= 10000;

% number of available mussels is 12000 grams
% medley one contains 30 grams of mussels and medley two contains 40 grams of mussels
constraint 30 * medley_one + 40 * medley_two <= 12000;

% number of available oysters is 11000 grams
% medley one contains 50 grams of mussels and medley two contains 20 grams of mussels
constraint 50 * medley_one + 20 * medley_two <= 11000;

% profit from medley one is $20 each and profit from medley two is $25 each 
var int: profit = 20 * medley_one + 25 * medley_two;

% maximize profit
solve maximize profit;

% output
output ["Seafood Medley One: " ++ show(medley_one) ++ "\nSeafood Medley Two: " ++ show(medley_two) ++ "\nProfit: $" ++ show(profit)];

var int: lab1_hours;
% hours lab 2 is run for
var int: lab2_hours;

% hours run is non-negative
constraint lab1_hours >= 0;
constraint lab2_hours >= 0;

% The company has 1500 worker hours available
% each session at lab 1 requires 3 hours of workers labor and each session at lab 2 requires 5 hours of worker labor
constraint lab1_hours * 3 + lab2_hours * 5 <= 1500;

% the company must make at least 20000 heart medication pills
% lab 1 can produce 20 heart medication pills per hour and lab 2 can produce 30 heart medication pills per hour
constraint lab1_hours * 20 + lab2_hours * 30 >= 20000;

% the company must make at least 30000 lung medication pills
% lab 1 can produce 30 lung medication pills per hour and lab 2 can produce 40 lung medication pills per hour
constraint lab1_hours * 30 + lab2_hours * 40 >= 30000;

% minimize the total time needed 
solve minimize lab1_hours + lab2_hours;

% Output
output ["Lab 1 hours: " ++ show(lab1_hours) ++ "\n" ++ "Lab 2 hours: " ++ show(lab2_hours)];

include "globals.mzn";

% number of regular packages
var int: regular;
% number of premium packages
var int: premium;

% number of packages must be non-negative
constraint regular >= 0;
constraint premium >= 0;

% 9000 units of medicinal herbs are available
% a regular package requires 100 grams of medicinal herbs and a premium package requires 130 grams of medicinal herbs
constraint regular * 100 + premium * 130 <= 9000;

% 3500 seconds are available in the drying machine
% a regular package requires 30 seconds of drying time and a premium package requires 60 seconds of drying time
constraint regular * 30 + premium * 60 <= 3500;

% number of regular packages must be less than the number of premium packages
constraint regular < premium;

% the company must make at least 15 regular packages
constraint regular >= 15;

% a regular package can treat 2 people and a premium package can treat 3 people
var int: total_people = regular * 2 + premium * 3;

solve maximize total_people;

output ["Regular Packages: " ++ show(regular) ++ "\n", "Premium Packages: " ++ show(premium) ++ "\n", "Total People: " ++ show(total_people) ++ "\n"];

include "globals.mzn";

% number of card-based machines
var int: card_machines;
% number of coin-based machines
var int: coin_machines;

% number of each machine must be non-negative
constraint card_machines >= 0;
constraint coin_machines >= 0;

% total number of guests accepted per hour must be greater than 1500
% card machines can accept 60 guests per hour and coin machines can accept 45 guests per hour
constraint card_machines * 60 + coin_machines * 45 >= 1500;

% total units of electricity used per hour must be less than 145
% card machines use 6 units of electricity per hour and coin machines use 4 units of electricity per hour
constraint card_machines * 6 + coin_machines * 4 <= 145;

% the number of card machines must be greater than the number of coin machines
constraint card_machines > coin_machines;

% minimize total machines
var int: total_machines = card_machines + coin_machines;
solve minimize total_machines;

% Output
output ["Number of card-based machines: " ++ show(card_machines) ++ "\nNumber of coin-based machines: " ++ show(coin_machines)];

include "globals.mzn";

% number of long-term cruise tickets
var 35..1500: long_term;
% number of week-long cruise tickets
var 0..1500: week_long;

% total number of people on the cruise ship
constraint long_term + week_long <= 1500;

% at least 4 times as many people prefer to buy week-long cruise tickets than long-term cruise tickets
constraint week_long >= 4 * long_term;

% profit from each type of ticket, 500 for long term and 150 for short term
var int: profit_long_term = 500 * long_term;
var int: profit_week_long = 150 * week_long;

% total profit
var int: total_profit = profit_long_term + profit_week_long;

% maximize total profit
solve maximize total_profit;

output ["Long-term tickets: " ++ show(long_term) ++ "\nWeek-long tickets: " ++ show(week_long) ++ "\nTotal profit: " ++ show(total_profit)];

var int: J; 
% number of process P
var int: P;

% number of processes are non-negative
constraint J >= 0;
constraint P >= 0;

% there can be at most 1500 units of water
% process J uses 8 units of water and process P uses 6 units of water
constraint 8*J + 6*P <= 1500;

% there can be at most 1350 units of pollution
% process J produces 3 units of pollution and process P produces 5 units of pollution
constraint 3*J + 5*P <= 1350;

% process J extracts 5 units of metal and process P extracts 9 units of metal
var int: metal = 5*J + 9*P;

% maximize the amount of metal extracted
solve maximize metal;

% output
output ["Process J: ", show(J), "\n", "Process P: ", show(P), "\n", "Max metal: ", show(metal)];

include "globals.mzn";

% number of bulldozers and forklifts
