  solve maximize profit;

  output ["Heated Seats: " ++ show(heated_seats) ++ "\n" ++ "Regular Seats: " ++ show(regular_seats) ++ "\n" ++ "Profit: $" ++ show(profit)];

var int: tube_trailers;
% number of trips by hydrogen tanker
var int: hydrogen_tankers;

% trips are non-negative
constraint tube_trailers >= 0;
constraint hydrogen_tankers >= 0;

% the company needs to transport at least 1000 cubic meters of hydrogen
% high-pressure tube trailer can transport 50 cubic meters each per trip and hydrogen_tankers 30 cubic meters per trip
constraint tube_trailers * 50 + hydrogen_tankers * 30 >= 1000;
% they have budget of $ 3750 available
% cost of trip is 500 per tube trailer and 200 per hydrogen tanker
constraint tube_trailers * 500 + hydrogen_tankers * 200 <= 3750;

% the number of transports done by the high pressure tube trailer method has to be less than the number of transports done by the liquefied hydrogen tanker method
constraint tube_trailers < hydrogen_tankers;

% minimize total number of trips
solve minimize tube_trailers + hydrogen_tankers;

% output
output ["High Pressure Tube Trailers: " ++ show(tube_trailers) ++ "\nLiquefied Hydrogen Tankers: " ++ show(hydrogen_tankers)];

var int: XYZ;
% number of servings of vitamin ABC
var int: ABC; 

% number of servings is non-negative
constraint XYZ >= 0;
constraint ABC >= 0;
% at least 30 mg of vitamin
% XYZ contains 2mg of vitamin and ABC contains 1.5mg
constraint XYZ * 2 + ABC * 1.5 >= 30;
% at least 55 mg of fiber
% XYZ contains 5mg of fiber and ABC contains 3mg
constraint XYZ * 5 + ABC * 3 >= 55; 
% at most 40% of the supplements taken from super vitamin XYZ
constraint XYZ <= 0.4 * (XYZ + ABC);
% at least 3 servings of super vitamin XYZ
constraint XYZ >= 3;

% XYZ causes 2 units of drowsiness per serving and ABC causes 3 units of drowsiness per serving
var int: drowsiness = XYZ * 2 + ABC * 3;

% minimize drowsiness
solve minimize drowsiness;

output ["XYZ: " ++ show(XYZ) ++ "\n", "ABC: " ++ show(ABC) ++ "\n", "Drowsiness: " ++ show(drowsiness)];

var 0..120: x1;
% number of bottles of ginger bubble tea
var 0..200: x2; 

% the store can make a maximum of 300 bottles of bubble tea per day
constraint x1 + x2 <= 300;

% profit from almond bubble tea is $5 each and from ginger bubble tea is $9 each
var int: profit = 5*x1 + 9*x2;

% maximize profit
solve maximize profit;

output ["Almond bubble tea: " ++ show(x1) ++ "\nGinger bubble tea: " ++ show(x2) ++ "\nProfit: $" ++ show(profit)];

var int: paperback;
% number of hardcover books produced
var int: hardcover;

% number of books is non-negative
constraint paperback >= 0;
constraint hardcover >= 0;

% there must be at least three times as many hardcover than paperback textbooks
constraint hardcover >= 3 * paperback;
% at least 100 paperback versions must be created
constraint paperback >= 100;
% the professor sells at least 1000 textbooks every year
constraint paperback + hardcover >= 1000;

% Paperback books yield a profit of $150 USD whereas hardcover versions yield a profit of $200 USD
var int: profit = 150 * paperback + 200 * hardcover;

% maximize profit
solve maximize profit; 

output ["Paperback: " ++ show(paperback) ++ "\n", "Hardcover: " ++ show(hardcover) ++ "\n", "Profit: " ++ show(profit) ++ "\n"];

var int: new_grads;
% number of senior engineers
var int: senior;

% number of engineers is non-negative
constraint new_grads >= 0;
constraint senior >= 0;

% there are at least 50 engineers
constraint new_grads + senior >= 50;
% there are at least 10 senior engineers
constraint senior >= 10;
% senior engineers should be at least a third the number of new grad engineers
constraint senior >= new_grads / 3;

% new grad engineers earn 1000 a week and senior engineers earn 3000 a week
var int: wage_bill = 1000*new_grads + 3000*senior;

% weekly wage bill must be kept below $ 100000 
constraint wage_bill <= 100000;

% minimize the wage_bill
solve minimize wage_bill;

var int: calcium;
% vitamin D pills
var int: vitaminD;

% pills takes are non-negative
constraint calcium >= 0;
constraint vitaminD >= 0;

% the student must take at least 130 pills of medication
constraint calcium + vitaminD >= 130;
% at least 40 of the total pills must be vitamin D pills
constraint vitaminD >= 40;
% the student must take more calcium pills than vitamin D pills
constraint calcium > vitaminD;

% calcium pills take 5 minutes to be effective and vitamin D pills take 6 minutes to be effective
var int: total_time = calcium * 5 + vitaminD * 6;

% minimize total time for the pills to be effective
solve minimize total_time;

output ["Calcium: " ++ show(calcium) ++ "\n", "Vitamin D: " ++ show(vitaminD) ++ "\n", "Total time: " ++ show(total_time) ++ " minutes\n"];

var int: juice;
% number of cups of milk
var int: milk;

% number of cups are non-negative
constraint juice >= 0;
constraint milk >= 0;

% patient needs to consume at least 180 units of vitamins
% juice contains 12 units of vitamins and milk contains 14 units of vitamins
constraint 12*juice + 14*milk >= 180;
% patient needs to consume at least 140 units of hydration
% juice contains 8 units of hydration and milk contains 10 units of hydration
constraint 8*juice + 10*milk >= 140;

% there must be at most 10% of all cups of drinks be vitamin-added milk
constraint milk <= 0.1*(juice + milk);

% juice contains 10 units of sugar and milk contains 3 units of sugar
var int: sugar = 10*juice + 3*milk;

% minize sugar intake
solve minimize sugar;

output ["Juice: " ++ show(juice) ++ "\nMilk: " ++ show(milk)];

var int: manual_jacks;
% number of electric jacks
var int: electric_jacks;

% number of jacks must be greater than 0
constraint manual_jacks >= 0;
constraint electric_jacks >= 0;

% number of manual jacks is at most 6
constraint manual_jacks <= 6;
% number of manual jacks is at most 8
constraint manual_jacks <= 8;
% number of electric jacks is at most 15
constraint electric_jacks <= 15;
% number of electric jacks is at least 5
constraint electric_jacks >= 5;

% number of electric jacks must be greater than the number of manual jacks
constraint electric_jacks > manual_jacks;

% manual jacks can transport 15 boxes every hour and electric jacks can transport 25 boxes every hour
var int: boxes = 15 * manual_jacks + 25 * electric_jacks;

% maximize the number of boxes
solve maximize boxes;
output ["Manual Pallet Jacks: " ++ show(manual_jacks) ++ "\n" ++ "Electric Pallet Jacks: " ++ show(electric_jacks) ++ "\n" ++ "Max Boxes: " ++ show(boxes)];

var int: silver_days;
% days spent at lucent beach
var int: lucent_days;

constraint silver_days >= 0;
constraint lucent_days >= 0;

% Jack needs to find at least 80 shrimps
% Jack finds 7 shrimps each day at silver beach and 4 each day at lucent beach
constraint silver_days * 7 + lucent_days * 4 >= 80;

% Jack needs to find at least 50 shrimps
% Jack finds 7 shrimps each day at silver beach and 4 each day at lucent beach
constraint silver_days * 3 + lucent_days * 6 >= 50;

var int: total_days = silver_days + lucent_days;

% minimizing the total days spent at the beaches
solve minimize total_days;

output ["Silver Beach Days: " ++ show(silver_days), "\nLucent Beach Days: " ++ show(lucent_days), "\nTotal Days: " ++ show(total_days)];

include "globals.mzn";

% Number of limousines and buses
var 0..100: limousines;
var 0..100: buses;

% they need to transport at least 400 people
% limousines can carry 12 people and buses can carry 18 people 
constraint limousines * 12 + buses * 18 >= 400;

% at least 70 % of the vehicles must be limousines
constraint limousines >= 0.7 * (limousines + buses);

% minimize the total number of limousines and buses used
solve minimize limousines + buses;

% output
output ["Number of limousines: ", show(limousines), "\n", "Number of buses: ", show(buses)];

var int: boat_trips;
% number of neighbor trips
var int: neighbor_trips; 

% number of trips are non-negative
constraint boat_trips >= 0;
constraint neighbor_trips >= 0;

% man does not want to spend more than $500
% boat trips cost $30 and trips by his neighbor cost 8
constraint 30 * boat_trips + 8 * neighbor_trips <= 500;

% number of boat trips can not exceed the number of trips his neighbor does
constraint boat_trips <= neighbor_trips; 

% units of berries boat trips can take is 200 and trips by his neight can take is 40
var int: berries = 200 * boat_trips + 40 * neighbor_trips;

% maximize number of berries
solve maximize berries;

% output the solution
output ["boat_trips: ", show(boat_trips), "\n", "neighbor_trips: ", show(neighbor_trips)];

% Parameters
int: NumberOfLocations;
int: NumberOfCustomers;
array[1..NumberOfCustomers] of int: CustomerDemand;
array[1..NumberOfLocations, 1..NumberOfCustomers] of int: ServiceAllocationCost;
array[1..NumberOfLocations] of int: WarehouseCapacity;
array[1..NumberOfLocations] of int: MinimumDemandFromWarehouse;
int: MinimumOpenWarehouses;
int: MaximumOpenWarehouses;
array[1..NumberOfLocations] of int: WarehouseFixedCost;

% Decision Variables
array[1..NumberOfLocations] of var 0..1: WarehouseOpen; % 1 if warehouse is open, 0 otherwise
array[1..NumberOfLocations, 1..NumberOfCustomers] of var 0..1: ServiceAllocation; % 1 if customer is served by warehouse, 0 otherwise

% Constraints
constraint sum(WarehouseOpen) >= MinimumOpenWarehouses;
constraint sum(WarehouseOpen) <= MaximumOpenWarehouses;

% Each customer is served by exactly one warehouse
constraint forall(i in 1..NumberOfCustomers) (
    sum(j in 1..NumberOfLocations) (ServiceAllocation[j, i]) = 1
);

% If a warehouse is open, it serves at least the minimum demand
constraint forall(i in 1..NumberOfLocations) (
    WarehouseOpen[i] * MinimumDemandFromWarehouse[i] <= sum(j in 1..NumberOfCustomers) (ServiceAllocation[i, j] * CustomerDemand[j])
);

% A warehouse cannot serve more than its capacity
constraint forall(i in 1..NumberOfLocations) (
    sum(j in 1..NumberOfCustomers) (ServiceAllocation[i, j] * CustomerDemand[j]) <= WarehouseCapacity[i]
);

% If a warehouse is closed, it cannot serve any customers
constraint forall(i in 1..NumberOfLocations, j in 1..NumberOfCustomers) (
    ServiceAllocation[i, j] <= WarehouseOpen[i]
);

% Objective Function: Minimize total cost
var int: TotalCost = sum(i in 1..NumberOfLocations) (WarehouseOpen[i] * WarehouseFixedCost[i]) + sum(i in 1..NumberOfLocations, j in 1..NumberOfCustomers) (ServiceAllocation[i, j] * ServiceAllocationCost[i, j]);
solve minimize TotalCost;

% Output
output ["Total Cost: ", show(TotalCost), "\n"];

% Parameters
int: JobCount; % Number of jobs
int: MachineCount; % Number of machines
array[1..JobCount, 1..MachineCount] of int: ProcessingTime; % Processing time for each job on each machine

% Decision Variables
array[1..JobCount] of var 1..JobCount: JobSequence; % Sequence of jobs
array[1..JobCount, 1..MachineCount] of var 0..sum(ProcessingTime) : StartTime; % Start time for each job on each machine

% Constraints
% Each job must be processed once
constraint alldifferent(JobSequence);

% The start time of the first job on the first machine is 0
constraint StartTime[1,1] = 0;

% The start time of each job on the first machine is the end time of the previous job on the first machine
constraint forall(j in 2..JobCount) (
    StartTime[j,1] = StartTime[j-1,1] + ProcessingTime[JobSequence[j-1],1]
);

% The start time of each job on each machine (except the first) is the maximum of the end time of the previous job on the same machine and the end time of the same job on the previous machine
constraint forall(j in 1..JobCount, m in 2..MachineCount) (
    StartTime[j,m] >= StartTime[j,m-1] + ProcessingTime[JobSequence[j],m-1]
);
constraint forall(j in 2..JobCount, m in 2..MachineCount) (
    StartTime[j,m] >= StartTime[j-1,m] + ProcessingTime[JobSequence[j-1],m]
);

% Objective
% Minimize the makespan, which is the end time of the last job on the last machine
var int: Makespan = StartTime[JobCount,MachineCount] + ProcessingTime[JobSequence[JobCount],MachineCount];
solve minimize Makespan;

% Output
output ["Job Sequence: ", show(JobSequence), "\nMakespan: ", show(Makespan)];

% Parameters
int: TotalAircraft;
int: TotalRoutes;
array[1..TotalAircraft] of int: Availability;
array[1..TotalRoutes] of int: Demand;
array[1..TotalAircraft, 1..TotalRoutes] of int: Capacity;
array[1..TotalAircraft, 1..TotalRoutes] of int: Costs;

% Decision Variables
array[1..TotalAircraft, 1..TotalRoutes] of var 0..1: Assign;

% Objective: Minimize total cost
var int: TotalCost = sum(i in 1..TotalAircraft, j in 1..TotalRoutes)(Assign[i,j]*Costs[i,j]);
minimize TotalCost;

% Constraints
% Each aircraft can be assigned to a maximum of its availability
constraint forall(i in 1..TotalAircraft)(sum(j in 1..TotalRoutes)(Assign[i,j]) <= Availability[i]);

% The total capacity assigned to each route must meet its demand
constraint forall(j in 1..TotalRoutes)(sum(i in 1..TotalAircraft)(Assign[i,j]*Capacity[i,j]) >= Demand[j]);

% An aircraft can only be assigned to a route if it has the capacity to service it
constraint forall(i in 1..TotalAircraft, j in 1..TotalRoutes)(Assign[i,j] <= Capacity[i,j]);

solve satisfy;

% Parameters
int: OriginNum;
int: DestinationNum;
array[1..OriginNum] of int: Supply;
array[1..DestinationNum] of int: Demand;
array[1..OriginNum, 1..DestinationNum] of int: Cost;

% Decision Variables
array[1..OriginNum, 1..DestinationNum] of var 0..max(Supply) : Transport;

% Constraints
% The total goods transported from each origin should not exceed its supply
constraint forall(i in 1..OriginNum) (
    sum(j in 1..DestinationNum) (Transport[i,j]) <= Supply[i]
);

% The total goods transported to each destination should meet its demand
constraint forall(j in 1..DestinationNum) (
    sum(i in 1..OriginNum) (Transport[i,j]) = Demand[j]
);

% Objective
var int: TotalCost = sum(i in 1..OriginNum, j in 1..DestinationNum) (Transport[i,j] * Cost[i,j]);
solve minimize TotalCost;

% Output
output [ "Transport[" ++ show(i) ++ "," ++ show(j) ++ "]=" ++ show(Transport[i,j]) ++ "\n" | i in 1..OriginNum, j in 1..DestinationNum ];

% Parameters
int: AlloysOnMarket;
int: RequiredElements;
array[1..RequiredElements, 1..AlloysOnMarket] of float: CompositionDataPercentage;
array[1..RequiredElements] of float: DesiredBlendPercentage;
array[1..AlloysOnMarket] of int: AlloyPrice;

% Decision Variables
array[1..AlloysOnMarket] of var 0..100: AlloyQuantity;

% Constraints
constraint forall(e in 1..RequiredElements)(
    sum(a in 1..AlloysOnMarket)(CompositionDataPercentage[e,a]*AlloyQuantity[a]) = DesiredBlendPercentage[e]*sum(a in 1..AlloysOnMarket)(AlloyQuantity[a])
);

% Objective
var int: TotalCost = sum(a in 1..AlloysOnMarket)(AlloyPrice[a]*AlloyQuantity[a]);
solve minimize TotalCost;

% Output
output ["AlloyQuantity: ", show(AlloyQuantity), "\n", "TotalCost: ", show(TotalCost)];

% Number of origins and destinations
int: NumberOfOrigins;
int: NumberOfDestinations;

% Supply of each origin and demand of each destination
array[1..NumberOfOrigins] of int: SupplyOfOrigin;
array[1..NumberOfDestinations] of int: DemandOfDestination;

% Cost of transporting from an origin to a destination
array[1..NumberOfOrigins, 1..NumberOfDestinations] of int: CostPerUnit;

% Decision variable: amount transported from each origin to each destination
array[1..NumberOfOrigins, 1..NumberOfDestinations] of var 0..max(SupplyOfOrigin): Transport;

% Objective: Minimize the total cost of transportation
minimize sum(i in 1..NumberOfOrigins, j in 1..NumberOfDestinations) (Transport[i,j] * CostPerUnit[i,j]);

% Constraints: The total supply from each origin and the total demand at each destination must be met
constraint forall(i in 1..NumberOfOrigins) (sum(j in 1..NumberOfDestinations) (Transport[i,j]) = SupplyOfOrigin[i]);
constraint forall(j in 1..NumberOfDestinations) (sum(i in 1..NumberOfOrigins) (Transport[i,j]) = DemandOfDestination[j]);

solve satisfy;

% Parameters
int: TotalAircrafts;
array[1..TotalAircrafts] of int: EarliestLandingTime;
array[1..TotalAircrafts] of int: TargetLandingTime;
array[1..TotalAircrafts] of int: LatestLandingTime;
array[1..TotalAircrafts] of int: PenaltyTimeAfterTarget;
array[1..TotalAircrafts] of int: PenaltyTimeBeforeTarget;
array[1..TotalAircrafts, 1..TotalAircrafts] of int: SeparationTimeMatrix;

% Decision Variables
array[1..TotalAircrafts] of var EarliestLandingTime[i]..LatestLandingTime[i]: LandingTime;

% Constraints
constraint forall(i in 1..TotalAircrafts, j in i+1..TotalAircrafts) (
    LandingTime[j] >= LandingTime[i] + SeparationTimeMatrix[i,j]
);

% Objective Function
var int: TotalPenalty = sum(i in 1..TotalAircrafts) (
    if LandingTime[i] > TargetLandingTime[i] then
        (LandingTime[i] - TargetLandingTime[i]) * PenaltyTimeAfterTarget[i]
    elseif LandingTime[i] < TargetLandingTime[i] then
        (TargetLandingTime[i] - LandingTime[i]) * PenaltyTimeBeforeTarget[i]
    else
        0
    endif
);

% Solve
solve minimize TotalPenalty;

% Output
output [ "LandingTime for Aircraft " ++ show(i) ++ ": " ++ show(LandingTime[i]) ++ "\n" | i in 1..TotalAircrafts ];

data.dzn:
ProductNum = 3;
ProductionRate = [200, 140, 160];
ProfitPerTon = [25, 30, 29];
MinimumSale = [1000, 500, 750];
MaximumSale = [6000, 4000, 3500];
AvailableHours = 40;

model.mzn:
% Parameters
int: NumberOfFacilities;
int: NumberOfCustomers;
array[1..NumberOfFacilities] of int: FacilityFixedCost;
array[1..NumberOfFacilities, 1..NumberOfCustomers] of int: FacilityToCustomerTransportCost;
array[1..NumberOfFacilities] of int: FacilityCapacity;
array[1..NumberOfCustomers] of int: CustomerDemand;

% Decision Variables
array[1..NumberOfFacilities, 1..NumberOfCustomers] of var 0..1: x; % x[i,j] = 1 if facility i serves customer j
array[1..NumberOfFacilities] of var 0..1: y; % y[i] = 1 if facility i is open

% Constraints
% Each customer is served by exactly one facility
constraint forall(j in 1..NumberOfCustomers) (
    sum(i in 1..NumberOfFacilities) (x[i,j]) = 1
);

% Facility capacity constraints
constraint forall(i in 1..NumberOfFacilities) (
    sum(j in 1..NumberOfCustomers) (x[i,j] * CustomerDemand[j]) <= FacilityCapacity[i] * y[i]
);

% If a facility is not open, it cannot serve any customers
constraint forall(i in 1..NumberOfFacilities, j in 1..NumberOfCustomers) (
    x[i,j] <= y[i]
);

% Objective Function: Minimize total cost
var int: total_cost = sum(i in 1..NumberOfFacilities) (y[i] * FacilityFixedCost[i]) + sum(i in 1..NumberOfFacilities, j in 1..NumberOfCustomers) (x[i,j] * FacilityToCustomerTransportCost[i,j]);
solve minimize total_cost;

% Output
output [ "Total Cost: " ++ show(total_cost) ++ "\n" ];

% Define parameters
int: OriginNum;
int: DestinationNum;
int: ProductNum;
array[1..OriginNum, 1..ProductNum] of int: Supply;
array[1..DestinationNum, 1..ProductNum] of int: Demand;
array[1..OriginNum, 1..DestinationNum] of int: Limit;
array[1..OriginNum, 1..DestinationNum, 1..ProductNum] of int: Cost;

% Define decision variables
array[1..OriginNum, 1..DestinationNum, 1..ProductNum] of var 0..max(Supply) + max(Demand): Shipment;

% Objective: Minimize total cost
var int: TotalCost = sum(i in 1..OriginNum, j in 1..DestinationNum, p in 1..ProductNum) (Cost[i,j,p] * Shipment[i,j,p]);
minimize TotalCost;

% Constraints
% Total amount of each product shipped from each origin equals its supply
constraint forall(i in 1..OriginNum, p in 1..ProductNum) (sum(j in 1..DestinationNum) (Shipment[i,j,p]) = Supply[i,p]);

% Total amount of each product shipped to each destination equals its demand
constraint forall(j in 1..DestinationNum, p in 1..ProductNum) (sum(i in 1..OriginNum) (Shipment[i,j,p]) = Demand[j,p]);

% Total amount of all products shipped from each origin to each destination does not exceed limit
constraint forall(i in 1..OriginNum, j in 1..DestinationNum) (sum(p in 1..ProductNum) (Shipment[i,j,p]) <= Limit[i,j]);

% Output
output ["Total Cost: ", show(TotalCost)];

% Parameters
int: NumItems;
int: NumPeriods;
array[1..NumItems, 1..NumPeriods] of int: Demand;
array[1..NumPeriods] of int: TotalPeriodCapacity;
array[1..NumItems, 1..NumPeriods] of int: ItemCapacity;
array[1..NumItems] of int: HoldingCost;
array[1..NumItems] of int: BackorderCost;
array[1..NumItems] of int: FixedCost;
array[1..NumItems] of int: InitialStock;

% Decision Variables
array[1..NumItems, 1..NumPeriods] of var 0..TotalPeriodCapacity[NumPeriods]: Production;
array[1..NumItems, 1..NumPeriods] of var 0..TotalPeriodCapacity[NumPeriods]: Stock;
array[1..NumItems, 1..NumPeriods] of var 0..1: Order;

% Constraints
constraint forall(i in 1..NumItems, j in 1..NumPeriods) (
    if j = 1 then
        Stock[i,j] = InitialStock[i] + Production[i,j] - Demand[i,j]
    else
        Stock[i,j] = Stock[i,j-1] + Production[i,j] - Demand[i,j]
    endif
);

constraint forall(j in 1..NumPeriods) (
    sum(i in 1..NumItems) (Production[i,j]) <= TotalPeriodCapacity[j]
);

constraint forall(i in 1..NumItems, j in 1..NumPeriods) (
    Production[i,j] <= ItemCapacity[i,j] * Order[i,j]
);

% Objective Function
var int: TotalCost = sum(i in 1..NumItems, j in 1..NumPeriods) (
    HoldingCost[i] * max(0, Stock[i,j]) +
    BackorderCost[i] * max(0, -Stock[i,j]) +
    FixedCost[i] * Order[i,j]
);

solve minimize TotalCost;

% Output
output [ "Total Cost: " ++ show(TotalCost) ++ "\n" ];

% Parameters
int: ElementNum;
array[1..ElementNum] of int: CoefficientA;
array[1..ElementNum] of int: ProfitCoefficientC;
array[1..ElementNum] of int: UpperBoundU;
int: GlobalParameterB;

% Decision Variables
array[1..ElementNum] of var 0..max(UpperBoundU): DecisionVariableX;

% Objective
maximize sum(j in 1..ElementNum) (ProfitCoefficientC[j] * DecisionVariableX[j]);

% Constraints
constraint sum(j in 1..ElementNum) ((1.0/CoefficientA[j]) * DecisionVariableX[j]) <= GlobalParameterB;
constraint forall(j in 1..ElementNum) (DecisionVariableX[j] >= 0 /\ DecisionVariableX[j] <= UpperBoundU[j]);

% Number of customers and vehicles
int: num_customers;
int: num_vehicles;

% Customer demands, time windows, distances and service times
array[1..num_customers] of int: customer_demand;
array[1..num_customers] of int: customer_LBTW;
array[1..num_customers] of int: customer_UBTW;
array[1..num_customers, 1..num_customers] of int: customer_distance;
array[1..num_customers] of int: customer_service_time;

% Vehicle capacities
array[1..num_vehicles] of int: vehicle_capacity;

% Decision variables
array[1..num_vehicles, 1..num_customers] of var 0..1: x; % x[i,j] = 1 if vehicle i serves customer j
array[1..num_vehicles, 1..num_customers] of var int: arrival_time; % arrival time of vehicle i at customer j

% Objective: Minimize the total distance travelled by all vehicles
var int: total_distance = sum(i in 1..num_vehicles, j in 1..num_customers, k in 1..num_customers) (x[i,j]*x[i,k]*customer_distance[j,k]);
minimize total_distance;

% Constraints
% Each customer is served by exactly one vehicle
constraint forall(j in 1..num_customers) (sum(i in 1..num_vehicles) (x[i,j]) = 1);

% The total demand served by each vehicle does not exceed its capacity
constraint forall(i in 1..num_vehicles) (sum(j in 1..num_customers) (x[i,j]*customer_demand[j]) <= vehicle_capacity[i]);

% The arrival time at each customer is within the customer's time window
constraint forall(i in 1..num_vehicles, j in 1..num_customers) (arrival_time[i,j] >= customer_LBTW[j]*x[i,j] /\ arrival_time[i,j] <= customer_UBTW[j]*x[i,j]);

% The arrival time at each customer is after the departure time from the previous customer
constraint forall(i in 1..num_vehicles, j in 1..num_customers, k in 1..num_customers) (arrival_time[i,j] >= arrival_time[i,k] + customer_service_time[k]*x[i,k] + customer_distance[k,j]*x[i,j]*x[i,k]);

% The arrival time at each customer is before the departure time to the next customer
constraint forall(i in 1..num_vehicles, j in 1..num_customers, k in 1..num_customers) (arrival_time[i,j] + customer_service_time[j]*x[i,j] + customer_distance[j,k]*x[i,j]*x[i,k] <= arrival_time[i,k]);

solve satisfy;

% Employee Assignment Problem
% Goal: Assign employees to shifts in different restaurants based on skills and preferences

% Input parameters
int: NumRestaurants;     % Number of restaurants
int: NumEmployees;       % Number of employees
int: NumShifts;          % Number of shifts per day
int: NumSkills;          % Number of possible skills

% 3D array: Demand[restaurant, shift, skill]
array[1..NumRestaurants, 1..NumShifts, 1..NumSkills] of int: Demand;

% 2D array: EmployeeSkills[employee, skill] - 1 if employee has the skill, 0 otherwise
array[1..NumEmployees, 1..NumSkills] of int: EmployeeSkills;

% 2D array: SkillPreference[employee, skill] - preference level of employee for each skill
array[1..NumEmployees, 1..NumSkills] of int: SkillPreference;

% 2D array: ShiftAvailability[employee, shift] - 1 if employee is available for the shift, 0 otherwise
array[1..NumEmployees, 1..NumShifts] of int: ShiftAvailability;

% Cost weight for unfulfilled positions
int: UnfulfilledPositionWeight;

% Decision variable: Assignment[restaurant, shift, skill, employee] - 1 if employee is assigned, 0 otherwise
array[1..NumRestaurants, 1..NumShifts, 1..NumSkills, 1..NumEmployees] of var 0..1: Assignment;

% Constraint: Each demand for a skill in a restaurant shift should be met by assigned employees
constraint
    forall(r in 1..NumRestaurants, s in 1..NumShifts, k in 1..NumSkills) (
        sum(e in 1..NumEmployees) (
            Assignment[r, s, k, e] * EmployeeSkills[e, k] * ShiftAvailability[e, s]
        ) >= Demand[r, s, k]
    );

% Objective: Minimize the cost of unfulfilled positions and less preferred assignments
var int: total_cost;

% Cost of unfulfilled positions
var int: unfulfilled_cost = sum(r in 1..NumRestaurants, s in 1..NumShifts, k in 1..NumSkills) (
    let {
        var int: fulfilled_positions = sum(e in 1..NumEmployees) (
            Assignment[r, s, k, e] * EmployeeSkills[e, k] * ShiftAvailability[e, s]
        )
    } in max(0, Demand[r, s, k] - fulfilled_positions) * UnfulfilledPositionWeight
);

% Cost of assigning employees to less preferred positions
var int: preference_cost = sum(r in 1..NumRestaurants, s in 1..NumShifts, k in 1..NumSkills, e in 1..NumEmployees) (
    Assignment[r, s, k, e] * (10 - SkillPreference[e, k])
);

% Total cost
constraint total_cost = unfulfilled_cost + preference_cost;

% Minimize the total cost
solve minimize total_cost;

% Output the assignment schedule
output [
    "Assignment Schedule:\n" ++
    concat([
        "Restaurant ", show(r), ", Shift ", show(s), ", Skill ", show(k), ": " ++
        concat([ if Assignment[r, s, k, e] = 1 then "Employee " ++ show(e) ++ " " else "" endif | e in 1..NumEmployees ]) ++ "\n"
        | r in 1..NumRestaurants, s in 1..NumShifts, k in 1..NumSkills
    ])
];

