model.mzn:
% Parameters
int: NutrientCount;
int: FoodCount;
array[1..FoodCount] of int: Cost;
array[1..FoodCount] of int: FoodMin;
array[1..FoodCount] of int: FoodMax;
array[1..NutrientCount] of int: NutrientMin;
array[1..NutrientCount] of int: NutrientMax;
array[1..NutrientCount, 1..FoodCount] of int: AmountNutrient;

% Decision Variables
array[1..FoodCount] of var FoodMin[1]..FoodMax[1]: FoodAmount;

% Objective
var int: TotalCost = sum(j in 1..FoodCount)(Cost[j]*FoodAmount[j]);
minimize TotalCost;

% Constraints
constraint forall(i in 1..NutrientCount)(
    sum(j in 1..FoodCount)(AmountNutrient[i,j]*FoodAmount[j]) >= NutrientMin[i] /\
    sum(j in 1..FoodCount)(AmountNutrient[i,j]*FoodAmount[j]) <= NutrientMax[i]
);

% Output
output ["Total cost: ", show(TotalCost), "\n"] ++
["Food amounts: "] ++ [show(FoodAmount[j]) | j in 1..FoodCount];

% Parameters
int: ParticipantNum;
int: CarNum;
array[1..ParticipantNum, 1..CarNum] of 0..1: InterestMatrix;

% Decision Variables
% AssignMatrix[p,c] is 1 if participant p is assigned to car c, 0 otherwise
array[1..ParticipantNum, 1..CarNum] of var 0..1: AssignMatrix;

% Objective
% Maximize the total number of assignments
var int: total_assignments = sum(p in 1..ParticipantNum, c in 1..CarNum) (AssignMatrix[p,c]);
maximize total_assignments;

% Constraints
% Each participant can be assigned to at most one car
constraint forall(p in 1..ParticipantNum) (sum(c in 1..CarNum) (AssignMatrix[p,c]) <= 1);

% Each car can be assigned to at most one participant
constraint forall(c in 1..CarNum) (sum(p in 1..ParticipantNum) (AssignMatrix[p,c]) <= 1);

% A participant can only be assigned to a car if they are interested in it
constraint forall(p in 1..ParticipantNum, c in 1..CarNum) (AssignMatrix[p,c] <= InterestMatrix[p,c]);

% A car can only be assigned to a participant if they are interested in it
constraint forall(p in 1..ParticipantNum, c in 1..CarNum) (AssignMatrix[p,c] >= InterestMatrix[p,c]);

% Solve
solve satisfy;

% Parameters
int: FoodNum;
int: NutrientNum;
array[1..FoodNum] of int: CostPerFood;
array[1..FoodNum] of int: FoodMin;
array[1..FoodNum] of int: FoodMax;
array[1..NutrientNum] of int: MinReqAmount;
array[1..NutrientNum] of int: MaxReqAmount;
array[1..FoodNum, 1..NutrientNum] of int: AmountPerNutrient;

% Decision Variables
array[1..FoodNum] of var FoodMin[1]..FoodMax[1]: FoodAmount;

% Objective
var int: TotalCost = sum(j in 1..FoodNum)(CostPerFood[j]*FoodAmount[j]);
minimize TotalCost;

% Constraints
constraint forall(i in 1..NutrientNum)(
    sum(j in 1..FoodNum)(AmountPerNutrient[j,i]*FoodAmount[j]) >= MinReqAmount[i] /\
    sum(j in 1..FoodNum)(AmountPerNutrient[j,i]*FoodAmount[j]) <= MaxReqAmount[i]
);

solve satisfy;
output [ "FoodAmount: \(FoodAmount)\nTotalCost: \(TotalCost)\n" ];

