        jim,edward,
        jim,maggy,
        edward,peter,
        edward,helen,
        edward,kitty,
        bill,fi]);

is_mother = array2d(1..2, 1..2, [
        maggy,fi,
        fi,lillian]);


age = [63, 37, 35, 43, 22, 85, 60, 33, 65];


output
[
  "X: " ++ show(X) ++ "\n" ++
  "Y: " ++ show(Y) ++ "\n"
];

