% int: n = 4; % n'th triangle number 1,3,6,10,15,...
% int: n = 5; 
int: n = 3; 
int: len = (n*(n + 1)) div 2;
array[1..len] of var 1..len: x;

% the triangle numbers for 1..n
array[1..n] of 1..len: t = [i*(i+1) div 2 | i in 1..n] ; 

% the index of first number to use in the subtraction
array[1..t[n-1]] of var 1..len: subs; 


predicate contains(var int: e, array[int] of var int: a) =
   exists(i in 1..length(a)) (
      a[i] = e
   )
;


% solve satisfy;
solve :: int_search(x ++ subs, first_fail, indomain_split, complete) satisfy;

constraint

   % create the array of numbers to subtract
   subs[1] = 2
   /\ 
   forall(i in 2..t[n-1]) (
      % "jump" of two when i-1 is a triangle number
      ( contains(i-1,t) ->  subs[i] = subs[i-1] + 2 )
      /\
      ( not (contains(i-1, t)) ->  subs[i] = subs[i-1] + 1  )
   )  

   /\ % position the balls in their places
   forall(i in 1..t[n-1]) (
      x[i] = abs(x[subs[i]]-x[subs[i]+1])
   )
   /\
   all_different(x)

   /\ % symmetry breaking
   x[2] < x[3] 
;

output [
 "x: ", show(x), "\n",
% "t: ", show(t), "\n",
% "subs: ", show(subs), "\n",
];

include "globals.mzn"; 

int: num_steps = 5; % i.e. the persistence
int: max_size = num_steps;

% decision variables
var 0..pow(10,max_size)-1: num; % the number to start with

array[0..num_steps, 1..max_size] of var 0..9: x;
array[0..num_steps] of var 1..pow(10,max_size)-1: nums;

% functions
function var int: to_num_base(array[int] of var int: a, int: base) =
          let { int: len = card(index_set(a));
                var int: n = sum(i in index_set(a)) (
                   pow(base, len-i) * a[i] 
                 );
         } in n
;

% base 10
function var int: to_num(array[int] of var int: a) = to_num_base(a, 10);

% solve satisfy;
solve minimize num;
% solve maximize num;
% solve :: int_search(array1d(x) ++ nums, first_fail, indomain_split, complete) minimize num;

constraint
  nums[0] = num /\
  nums[0] = to_num([x[0,i] | i in 1..max_size]) /\
  forall(s in 1..num_steps) (
    % note: don't multiply with leading 0's
    nums[s] = product([if x[s-1,i] > 0 then x[s-1,i] else 1 endif | i in 1..max_size]) 
    /\
    nums[s] = to_num([x[s,i] | i in 1..max_size])
  )

  /\ % we want a solution in exactly num_steps steps
  nums[num_steps] != nums[num_steps-1] 

  % redundant constraints
  /\ % requires that last number is a single digit
  forall(i in 1..max_size-1) ( x[num_steps,i] = 0)

  /\ nums[num_steps] < 10
  % /\ decreasing(nums) % much faster
;

output [
  "nums: \(nums)\n"
]
++
[
  if i = 1 then "\n" else " " endif ++
    show(x[s,i])
  | s in 0..num_steps, i in 1..max_size
]
;

