int: n = 3;
array[1..n, 1..n] of var 1..13: x;
var 0..13*4: s;

solve satisfy;
% solve maximize s;
% solve :: int_search([x[r,c] | r,c in 1..n], first_fail, indomain_min, complete) maximize s;

constraint

  % there are 4 cards of each value in a deck
  forall(i in 1..13) (
     % at_most(4, [x[r,c] | r,c in 1..n], i)
     count(t in [x[r,c] | r,c in 1..n]) (t = i) <= 4
  )

  % the standard magic square constraints (sans all_different)
  /\
  forall (c in 1..n) (sum (r in 1..n) (x[r, c]) = s)
  /\
  forall (r in 1..n) (sum (c in 1..n) (x[r, c]) = s)
  /\
  sum (i in 1..n) (x[i, i]) = s
  /\
  sum (i in 1..n) (x[i, n + 1 - i]) = s
;


output 
[
  "\ns: ", show(s)
] ++
[
  if c = 1 then "\n" else " " endif ++
    show(x[r,c])
  | r, c in 1..n
]
++ ["\n"]
;

include "globals.mzn"; 
int: n = 3;
array[1..n, 1..n] of var 1..n*n: x;
array[1..n] of var int: row_sums; % sum of the rows

predicate toNum10(array[int] of var int: a, var int: n) =
          let { int: len = length(a) }
          in
          n = sum(i in 1..len) (
            ceil(pow(10.0, int2float(len-i))) * a[i]
          )
          /\ forall(i in 1..len) (a[i] >= 0)
;


% solve satisfy;
solve :: int_search([x[i,j] | i,j in 1..n] ++ row_sums, first_fail, indomain_min, complete) satisfy;


constraint
   forall(i in 1..n) ( 
      row_sums[i] > 0
   )
   /\ 
   all_different([x[i,j] | i,j in 1..n])
   /\ % sum of rows
   forall(i in 1..n) (
      toNum10([x[i,j] | j in 1..n], row_sums[i])
   )
   /\ % sum of first 1..n-1 rows = n'th row
   sum(i in 1..n-1) (row_sums[i]) = row_sums[n]

   /\ % the rook moves
   forall(k in 1..n*n-1) (
     exists(i, j in 1..n) (
        k = x[i, j] % fix this k
        /\
        exists(a, b in {-1, 0, 1}
          where 
          i+a >= 1 /\ j+b >= 1 
          /\
          i+a <= n /\ j+b <= n
          /\ 
          abs(a+b) = 1 % just move in exactly one direction
        ) 
        (
          % find the next k
          k + 1 = x[i+a, j+b]  
        )
     )
  )
;


output 
[
  "\nrow_sums: ", show(row_sums)
] ++
[
  if j = 1 then "\n" else " " endif ++
    show(x[i,j])
  | i, j in 1..n
] ++ ["\n"]
;

