%% number of weight plates available. Divide the total number of weight plates by 4 
%% Eg. I have 12 0.5kg weights -> 3 in weight_avail, and 4 1.0kg weights (-> 1), etc.
% weight_avail = [   3,  1,  1,   1,  0,  1,   0,   0,   0,   0];  
