2, 3, 4, 5, 1,
4, 2, 3, 1, 5]);


output 
[
  "\njobs: ", show(jobs), "\n",
  "summax: ", show(summax)
] ++ 
[
   if j = 1 then "\n" else " " endif ++
   show(x[i,j]) 
   | i in 1..rows, j in 1..cols
] ++ ["\n"];

